import { app, BrowserWindow, dialog, ipcMain, shell } from 'electron';
import { spawn } from 'node:child_process';
import { isAuthorizedSender } from './ipc-sender-policy';
import { createDocumentHandoffHandler, FilePolicyError } from '../src/app/api/working-root/file/file-policy';
import { existsSync, mkdirSync } from 'node:fs';
import { stat } from 'node:fs/promises';
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import type { AddressInfo } from 'node:net';
import path from 'node:path';
import { RuntimeClient } from '@chirality/runtime-client';
import { ProjectRegistry } from '@chirality/runtime-core';
import { installRuntimeDaemonSignalShutdown } from '@chirality/runtime-daemon';
import { registerApiKeyHandlers, unregisterApiKeyHandlers } from './api-key-ipc';
import { installBundledCliLauncher } from './cli-launcher';
import {
  createDesktopLogger,
  createNoopDesktopLogger,
  type DesktopLogger
} from './desktop-log';
import {
  GUI_SPAWN_MIN_INTERVAL_MS,
  isDaemonGuiSpawnEnabled,
  resolveDaemonActivationPolicy,
  resolveUserDataOverride
} from './desktop-process-policy';
import {
  applyDesktopProjectBinding,
  DESKTOP_PROJECT_ID,
  prepareDesktopHarnessEnvironment,
  resolveDesktopProjectBinding
} from './desktop-project-client';
import { resolvePackagedDaemonInstructionRoot } from './daemon-instruction-root';
import {
  applyPackagedRendererRequestPolicy,
  buildRendererContentSecurityPolicy,
  installRendererWindowPolicy,
  rendererWebPreferences,
  runEgressLayerProbe,
  runRendererSecurityProbe
} from './renderer-window-policy';
import { startRuntimeHost, type RuntimeHost } from './runtime-host';
import {
  createRuntimeBindingSupervisor,
  RUNTIME_CONNECTIVITY_CHANGED_CHANNEL,
  RUNTIME_CONNECTIVITY_QUERY_CHANNEL,
  type RuntimeBindingSupervisor,
  type RuntimeConnectivitySnapshot
} from './runtime-connectivity';
import {
  createDesktopDaemonLifecycle,
  registerRuntimeControlHandlers,
  unregisterRuntimeControlHandlers
} from './runtime-control-ipc';
import {
  createSocketPresenceWatcher,
  type SocketPresenceWatcher
} from './runtime-socket-watch';
import { shouldPreventNativeQuit } from './runtime-shutdown-policy';

type RendererServer = {
  close: () => Promise<void>;
  url: string;
};

type RendererProbeResult = {
  url: string;
  ok: boolean;
  status: number | null;
  type: string | null;
  error: string | null;
};

const SELECT_DIRECTORY_CHANNEL = 'chirality:select-directory';
const RUNTIME_NETWORK_POLICY_ID = 'REQ-NET-001';
const DEFAULT_RENDERER_PROBE_DELAY_MS = 1500;
const DEFAULT_RENDERER_PROBE_TIMEOUT_MS = 8000;

const ALLOWED_ANTHROPIC_API_HOSTNAMES = new Set<string>(['api.anthropic.com']);
const ALLOWED_LOOPBACK_HOSTNAMES = new Set<string>(['localhost', '127.0.0.1', '[::1]']);
const RENDERER_EGRESS_FILTER_URLS = ['http://*/*', 'https://*/*', 'ws://*/*', 'wss://*/*'];

let rendererServer: RendererServer | undefined;
let runtimeHost: RuntimeHost | undefined;
let shutdownStarted = false;
let shutdownCompleted = false;
let bindingSupervisor: RuntimeBindingSupervisor | undefined;
let socketWatcher: SocketPresenceWatcher | undefined;
/** Monotonic timestamp of the last GUI spawned from daemon mode; see `activate`. */
let lastGuiSpawnAt = 0;
let desktopLogger: DesktopLogger = createNoopDesktopLogger();
const runtimeDaemonMode = process.argv.includes('--runtime-daemon');

/**
 * Honor `CHIRALITY_USER_DATA` for the app itself.
 *
 * The bundled `chirality` CLI and `@chirality/runtime-cli` already resolve their
 * runtime directory from `CHIRALITY_USER_DATA`, but the app hard-coded
 * Electron's default (`<appData>/chirality-frontend`). The two therefore
 * disagreed by default, and documented CLI commands pointed at a runtime
 * directory the app never used. Honoring the same variable here makes one
 * variable pin *both* sides to one runtime directory, and lets a verification
 * run drive a fully isolated app + daemon + LaunchAgent triple without touching
 * an operator's real userData.
 *
 * Must run before anything reads `app.getPath('userData')` and before `ready`,
 * because the value also selects the Chromium profile directory. Relative values
 * are rejected rather than resolved against an unpredictable cwd (launchd starts
 * jobs in `/`). `app.setPath` throws when the directory is absent, so create it
 * first. Applies to packaged and unpackaged runs alike — an env override that
 * silently only worked in one of them would be worse than none.
 */
function applyUserDataOverride(): void {
  const override = resolveUserDataOverride(process.env);
  if (override.kind === 'absent') {
    return;
  }
  if (override.kind === 'rejected') {
    console.warn(
      'Ignoring CHIRALITY_USER_DATA because it is not an absolute path',
      JSON.stringify({ requested: override.requested })
    );
    return;
  }
  try {
    mkdirSync(override.directory, { recursive: true, mode: 0o700 });
    app.setPath('userData', override.directory);
  } catch (error) {
    console.error(
      'Failed to apply CHIRALITY_USER_DATA override',
      error instanceof Error ? error.message : String(error)
    );
  }
}

/**
 * Shed the daemon's *app* identity while keeping it an Electron process.
 *
 * The daemon is the same bundle relaunched with `--runtime-daemon`, so without
 * this it comes up as an ordinary macOS application: Dock tile, menu bar, and —
 * decisively — a LaunchServices-visible, activatable instance of
 * `Chirality.app`. Opening the app from Finder/Dock then resolves against that
 * headless instance instead of starting the GUI, and the operator-visible effect
 * is "launching the GUI killed the daemon".
 *
 * `'prohibited'` is the strongest available posture ("doesn't appear in the Dock
 * and may not create windows or be activated") and is safe here precisely
 * because the daemon never creates a BrowserWindow. `'accessory'` remains
 * selectable through `CHIRALITY_DAEMON_ACTIVATION_POLICY` for comparison drills.
 *
 * safeStorage is unaffected: on macOS `safeStorage.isEncryptionAvailable()`
 * "returns true if Keychain is available" — it is gated on Keychain access, not
 * on NSApplication activation, a Dock tile, or a window. (Unlike Linux/Windows
 * it is not even gated on `ready`.) Keychain prompts are drawn by the system
 * security agent, not by this process's NSApplication.
 *
 * Called both at module scope and again after `ready`: the early call avoids a
 * visible Dock flash during launch, the later one is the belt-and-braces value
 * in case activation policy is reset while NSApplication finishes coming up.
 */
function applyDaemonActivationPolicy(): void {
  if (process.platform !== 'darwin') {
    return;
  }
  const policy = resolveDaemonActivationPolicy(process.env);
  try {
    app.setActivationPolicy(policy);
  } catch (error) {
    console.warn(
      'Failed to set the runtime daemon activation policy',
      JSON.stringify({ policy, error: error instanceof Error ? error.message : String(error) })
    );
  }
  if (policy === 'regular') {
    return;
  }
  try {
    app.dock?.hide();
  } catch {
    // A hidden or absent Dock tile is already the desired end state.
  }
}

applyUserDataOverride();
if (runtimeDaemonMode) {
  applyDaemonActivationPolicy();
}

type RendererEgressPolicyDecision =
  | { allowed: true }
  | { allowed: false; category: 'INVALID_URL' | 'NETWORK_POLICY_VIOLATION'; reason: string };

type RendererRequestDestination = {
  hostname: string;
  port: string | null;
  protocol: string;
};

function isAllowedLoopbackHostname(hostname: string): boolean {
  return ALLOWED_LOOPBACK_HOSTNAMES.has(hostname.toLowerCase());
}

function summarizeRendererRequestDestination(rawUrl: string): RendererRequestDestination | null {
  try {
    const parsed = new URL(rawUrl);
    return {
      hostname: parsed.hostname,
      port: parsed.port || null,
      protocol: parsed.protocol
    };
  } catch {
    return null;
  }
}

function parsePositiveInteger(raw: string | undefined, fallback: number): number {
  const parsed = Number.parseInt(raw ?? '', 10);
  if (!Number.isSafeInteger(parsed) || parsed <= 0) {
    return fallback;
  }
  return parsed;
}

function readRendererProbeUrls(): string[] {
  const raw = process.env.CHIRALITY_NETWORK_POLICY_PROBE_URLS?.trim();
  if (!raw) {
    return [];
  }

  return raw
    .split(',')
    .map((value) => value.trim())
    .filter((value) => value.length > 0);
}

function evaluateRendererEgressPolicy(rawUrl: string): RendererEgressPolicyDecision {
  let parsed: URL;
  try {
    parsed = new URL(rawUrl);
  } catch {
    return {
      allowed: false,
      category: 'INVALID_URL',
      reason: 'url_parse_failed'
    };
  }

  const hostname = parsed.hostname.toLowerCase();
  if (ALLOWED_ANTHROPIC_API_HOSTNAMES.has(hostname)) {
    if (parsed.protocol !== 'https:') {
      return {
        allowed: false,
        category: 'NETWORK_POLICY_VIOLATION',
        reason: `anthropic_protocol_not_allowlisted:${parsed.protocol}`
      };
    }

    if (parsed.port !== '' && parsed.port !== '443') {
      return {
        allowed: false,
        category: 'NETWORK_POLICY_VIOLATION',
        reason: `anthropic_port_not_allowlisted:${parsed.port}`
      };
    }

    return { allowed: true };
  }

  if (isAllowedLoopbackHostname(hostname)) {
    return { allowed: true };
  }

  return {
    allowed: false,
    category: 'NETWORK_POLICY_VIOLATION',
    reason: `host_not_allowlisted:${hostname}`
  };
}

function registerRendererEgressPolicy(window: BrowserWindow): void {
  window.webContents.session.webRequest.onBeforeRequest(
    { urls: RENDERER_EGRESS_FILTER_URLS },
    (details, callback) => {
      const decision = evaluateRendererEgressPolicy(details.url);
      if (decision.allowed) {
        callback({ cancel: false });
        return;
      }

      console.warn('Blocked renderer outbound request by network policy', {
        category: decision.category,
        policy: RUNTIME_NETWORK_POLICY_ID,
        reason: decision.reason,
        destination: summarizeRendererRequestDestination(details.url),
        method: details.method,
        resourceType: details.resourceType,
        webContentsId: details.webContentsId
      });

      callback({ cancel: true });
    }
  );
}

async function runRendererNetworkProbe(window: BrowserWindow): Promise<void> {
  const urls = readRendererProbeUrls();
  if (urls.length === 0) {
    return;
  }

  const delayMs = parsePositiveInteger(
    process.env.CHIRALITY_NETWORK_POLICY_PROBE_DELAY_MS,
    DEFAULT_RENDERER_PROBE_DELAY_MS
  );
  const timeoutMs = parsePositiveInteger(
    process.env.CHIRALITY_NETWORK_POLICY_PROBE_TIMEOUT_MS,
    DEFAULT_RENDERER_PROBE_TIMEOUT_MS
  );

  const runProbe = async (): Promise<void> => {
    const script = `
(() => {
  const urls = ${JSON.stringify(urls)};
  const timeoutMs = ${timeoutMs};
  const run = async () => {
    const results = [];
    for (const url of urls) {
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), timeoutMs);
      try {
        const response = await fetch(url, {
          method: 'GET',
          mode: 'no-cors',
          cache: 'no-store',
          signal: controller.signal
        });
        results.push({
          url,
          ok: true,
          status: typeof response?.status === 'number' ? response.status : null,
          type: typeof response?.type === 'string' ? response.type : null,
          error: null
        });
      } catch (error) {
        const errorMessage = error instanceof Error ? error.message : String(error);
        results.push({
          url,
          ok: false,
          status: null,
          type: null,
          error: errorMessage
        });
      } finally {
        clearTimeout(timer);
      }
    }
    return results;
  };
  return run();
})();
`;

    try {
      const results = (await window.webContents.executeJavaScript(script, true)) as RendererProbeResult[];
      console.info(
        '[network-policy-probe]',
        JSON.stringify({
          policy: RUNTIME_NETWORK_POLICY_ID,
          results
        })
      );
    } catch (error) {
      console.error(
        '[network-policy-probe]',
        JSON.stringify({
          policy: RUNTIME_NETWORK_POLICY_ID,
          error: error instanceof Error ? error.message : String(error)
        })
      );
    }
  };

  const scheduleProbe = (): void => {
    setTimeout(() => {
      void runProbe();
    }, delayMs);
  };

  if (window.webContents.isLoadingMainFrame()) {
    window.webContents.once('did-finish-load', scheduleProbe);
  } else {
    scheduleProbe();
  }
}

function resolveInstructionRootForProcess(): string {
  const envOverride = process.env.CHIRALITY_INSTRUCTION_ROOT?.trim();
  if (envOverride) {
    return path.resolve(envOverride);
  }

  if (app.isPackaged) {
    return path.resolve(process.resourcesPath);
  }

  const candidates: string[] = [];
  for (const start of [process.cwd(), __dirname]) {
    let candidate = path.resolve(start);
    for (;;) {
      candidates.push(candidate);
      const parent = path.dirname(candidate);
      if (parent === candidate) break;
      candidate = parent;
    }
  }
  const resolved = candidates.find(
    (candidate) =>
      existsSync(path.join(candidate, 'agents')) &&
      existsSync(path.join(candidate, 'AGENTS.md')) &&
      existsSync(path.join(candidate, 'docs', 'DIRECTIVE.md'))
  );
  if (resolved === undefined) {
    throw new Error('Unable to resolve the Chirality instruction root');
  }
  return resolved;
}

async function registerDirectorySelectionHandler(): Promise<void> {
  ipcMain.removeHandler(SELECT_DIRECTORY_CHANNEL);
  ipcMain.handle(SELECT_DIRECTORY_CHANNEL, async () => {
    const dialogResult = await dialog.showOpenDialog({
      title: 'Select Working Root',
      properties: ['openDirectory']
    });

    if (dialogResult.canceled || dialogResult.filePaths.length === 0) {
      return { cancelled: true };
    }

    const selectedPath = path.resolve(dialogResult.filePaths[0]);

    try {
      const selectedStat = await stat(selectedPath);
      if (!selectedStat.isDirectory()) {
        return {
          cancelled: true,
          error: 'Selected path is not a directory'
        };
      }
    } catch {
      return {
        cancelled: true,
        error: 'Selected path is not accessible'
      };
    }

    return {
      cancelled: false,
      path: selectedPath
    };
  });
}

async function startPackagedRendererServer(): Promise<RendererServer> {
  const rendererRoot = path.join(process.resourcesPath, 'app.asar');
  const nextModule = await import('next');
  const nextFactory = (nextModule.default ?? nextModule) as unknown as (config: {
    dev: boolean;
    dir: string;
  }) => {
    getRequestHandler: () => (
      req: IncomingMessage,
      res: ServerResponse<IncomingMessage>
    ) => Promise<void> | void;
    prepare: () => Promise<void>;
  };

  const nextApp = nextFactory({
    dev: false,
    dir: rendererRoot
  });

  await nextApp.prepare();
  const handle = nextApp.getRequestHandler();
  const server = createServer((req, res) => {
    // Derive the policy once per request and expose its nonce to Next before it
    // renders. The helper attaches the byte-identical policy to the response.
    applyPackagedRendererRequestPolicy(req, res);
    handle(req, res);
  });

  await new Promise<void>((resolve, reject) => {
    server.once('error', reject);
    server.listen(0, '127.0.0.1', () => {
      server.off('error', reject);
      resolve();
    });
  });

  const address = server.address() as AddressInfo | null;
  if (!address || typeof address === 'string') {
    throw new Error('Renderer server failed to bind a TCP port');
  }

  return {
    close: async () => {
      await new Promise<void>((resolve, reject) => {
        server.close((error) => {
          if (error) {
            reject(error);
            return;
          }
          resolve();
        });
      });
    },
    url: `http://127.0.0.1:${address.port}`
  };
}

const RENDERER_SECURITY_PROBE_ROUTES = ['/', '/chat', '/pipeline', '/workbench'] as const;

function createMainWindow(rendererUrl: string, route = '/'): BrowserWindow {
  const rendererOrigin = new URL(rendererUrl).origin;
  const rendererPageUrl = new URL(route, rendererUrl).toString();
  // Web preferences come from the hardening policy and are asserted there:
  // creation fails closed rather than producing a weaker window.
  const window = new BrowserWindow({
    width: 1280,
    height: 840,
    show: false,
    webPreferences: rendererWebPreferences({ preload: path.join(__dirname, 'preload.js') })
  });

  window.once('ready-to-show', () => {
    window.show();
  });

  registerRendererEgressPolicy(window);
  installRendererWindowPolicy(window, {
    rendererOrigin,
    // Packaged responses must keep the request nonce created by the custom
    // server; synthesizing a static response fallback here would disagree with
    // the rendered inline scripts. Development keeps its existing static
    // fallback and allowances.
    contentSecurityPolicy: app.isPackaged
      ? undefined
      : buildRendererContentSecurityPolicy({ mode: 'development', rendererOrigin }),
    // http(s) targets of a renderer window.open / target="_blank" go to the
    // system browser rather than a child window carrying this app's bridge.
    openExternal: (url) => shell.openExternal(url),
    log: (level, event, detail) => desktopLogger.log(level, event, detail)
  });
  window.loadURL(rendererPageUrl);
  void runRendererNetworkProbe(window);
  runRendererSecurityProbe(window, { env: process.env });
  runEgressLayerProbe(window, { env: process.env });

  return window;
}

function runtimeControlPaths(): {
  runtimeDirectory: string;
  socketPath: string;
  operatorTokenFile: string;
} {
  const runtimeDirectory = path.join(app.getPath('userData'), 'runtime');
  return {
    runtimeDirectory,
    socketPath:
      process.env.CHIRALITY_RUNTIME_SOCKET_PATH?.trim() ||
      path.join(runtimeDirectory, 'control.sock'),
    operatorTokenFile:
      process.env.CHIRALITY_RUNTIME_OPERATOR_TOKEN_FILE?.trim() ||
      path.join(runtimeDirectory, 'auth', 'tokens', 'operator.token')
  };
}

async function configureDesktopHarnessClient(
  operatorClient: RuntimeClient,
  control: ReturnType<typeof runtimeControlPaths>
): Promise<void> {
  prepareDesktopHarnessEnvironment(process.env, control.socketPath);

  const binding = await resolveDesktopProjectBinding({
    operatorClient,
    runtimeDirectory: control.runtimeDirectory,
    socketPath: control.socketPath
  });
  applyDesktopProjectBinding(process.env, binding);
}

/** Push a connectivity transition to every live renderer. */
function broadcastRuntimeConnectivity(snapshot: RuntimeConnectivitySnapshot): void {
  for (const window of BrowserWindow.getAllWindows()) {
    if (window.isDestroyed()) {
      continue;
    }
    window.webContents.send(RUNTIME_CONNECTIVITY_CHANGED_CHANNEL, snapshot);
  }
}

async function registerRuntimeConnectivityHandler(): Promise<void> {
  ipcMain.removeHandler(RUNTIME_CONNECTIVITY_QUERY_CHANNEL);
  ipcMain.handle(
    RUNTIME_CONNECTIVITY_QUERY_CHANNEL,
    async (): Promise<RuntimeConnectivitySnapshot | null> =>
      bindingSupervisor?.snapshot() ?? null
  );
}

async function initializeGui(): Promise<void> {
  const control = runtimeControlPaths();
  desktopLogger = createDesktopLogger({
    directory: path.join(app.getPath('userData'), 'logs')
  });
  const runtimeClient = new RuntimeClient({
    socketPath: control.socketPath,
    tokenFile: control.operatorTokenFile
  });
  await registerDirectorySelectionHandler();
  await registerRuntimeConnectivityHandler();
  process.env.CHIRALITY_INSTRUCTION_ROOT = resolveInstructionRootForProcess();
  desktopLogger.info('desktop.gui.starting', {
    packaged: app.isPackaged,
    userData: app.getPath('userData'),
    socketPath: control.socketPath
  });

  if (app.isPackaged) {
    // Log-and-continue, always: a convenience launcher that cannot be written
    // must never be able to stop the app from starting.
    await installBundledCliLauncher()
      .then((result) => {
        desktopLogger.info('desktop.cli_launcher.install', result);
      })
      .catch((error) => {
        desktopLogger.error('desktop.cli_launcher.install_failed', error);
      });
  }

  // Binding is a supervised main-process concern, not a one-shot startup step:
  // a daemon that is down at this instant, or that dies later, must not leave the
  // window permanently unable to reach the runtime. `start()` still awaits the
  // first attempt so a healthy daemon is fully bound before the window appears.
  bindingSupervisor = createRuntimeBindingSupervisor({
    bind: () => configureDesktopHarnessClient(runtimeClient, control),
    probe: async () => {
      try {
        await runtimeClient.daemonStatus();
        return true;
      } catch {
        return false;
      }
    },
    onStateChange: (snapshot) => {
      desktopLogger.info('runtime.connectivity.state', snapshot);
      broadcastRuntimeConnectivity(snapshot);
    },
    log: (level, event, detail) => desktopLogger.log(level, event, detail)
  });

  // The supervisor's timers alone make a daemon bounce cost up to a probe
  // interval to notice plus a walk up the retry ladder to undo — even when the
  // daemon came back in milliseconds, which is exactly what a Finder-launch
  // handoff does. The control socket's appearance and disappearance are the
  // same two facts, available immediately, so watching it turns both delays
  // into a single filesystem event. The ladder stays as the fallback for the
  // cases the filesystem cannot report (a SIGKILLed daemon leaves its socket
  // behind, and a daemon that is listening but unhealthy changes nothing).
  socketWatcher = createSocketPresenceWatcher({
    socketPath: control.socketPath,
    onChange: () => {
      void bindingSupervisor?.refreshNow();
    },
    log: (level, event, detail) => desktopLogger.log(level, event, detail)
  });
  socketWatcher.start();

  await bindingSupervisor.start();

  const rendererUrl = app.isPackaged
    ? (rendererServer = await startPackagedRendererServer()).url
    : process.env.ELECTRON_RENDERER_URL ?? 'http://localhost:3000';
  const rendererOrigin = new URL(rendererUrl).origin;

  // Credential channels are registered only once the renderer origin is known:
  // every one of them rejects senders from any other origin, so they cannot
  // exist before the origin does. The window is created after this, so no
  // renderer can invoke them in the gap.
  ipcMain.removeHandler('chirality:document-handoff');
  ipcMain.handle('chirality:document-handoff', createDocumentHandoffHandler<import('electron').IpcMainInvokeEvent>({
    authorized: (event) => isAuthorizedSender(event, rendererOrigin),
    instructionRoot: resolveInstructionRootForProcess,
    preview: (event, target) => {
      if (process.platform !== 'darwin') throw new FilePolicyError('QUICK_LOOK_UNAVAILABLE', 400, 'Quick Look requires macOS.');
      const window = BrowserWindow.fromWebContents(event.sender);
      if (!window || window.isDestroyed()) throw new FilePolicyError('WINDOW_UNAVAILABLE', 409, 'Document window is unavailable.');
      window.previewFile(target);
    },
    open: (target) => shell.openPath(target)
  }));

  registerApiKeyHandlers(runtimeClient, {
    rendererOrigin,
    log: (level, event, detail) => desktopLogger.log(level, event, detail)
  });

  registerRuntimeControlHandlers({
    client: runtimeClient,
    lifecycle: createDesktopDaemonLifecycle(),
    desktopExecutable: app.getPath('exe'),
    packaged: app.isPackaged,
    rendererOrigin,
    // An operator action that makes the daemon reachable should not have to wait
    // out the backoff ladder.
    onDaemonAvailable: async () => {
      await bindingSupervisor?.refreshNow();
    }
  });

  if (app.isPackaged && process.env.CHIRALITY_RENDERER_SECURITY_PROBE === '1') {
    // The isolated packaged proof loads every operator route in a real
    // BrowserWindow. Outside that explicit proof environment, startup remains
    // one window at `/` as before.
    for (const route of RENDERER_SECURITY_PROBE_ROUTES) {
      createMainWindow(rendererUrl, route);
    }
  } else {
    createMainWindow(rendererUrl);
  }

  app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) {
      createMainWindow(rendererUrl);
    }
  });
}

async function initializeDaemon(): Promise<void> {
  // Re-assert the headless posture now that NSApplication is fully up.
  applyDaemonActivationPolicy();
  desktopLogger = createDesktopLogger({
    directory: path.join(app.getPath('userData'), 'logs'),
    fileName: 'desktop-daemon.log'
  });
  if (app.isPackaged) {
    const control = runtimeControlPaths();
    const projects = new ProjectRegistry(control.runtimeDirectory);
    const resolution = await resolvePackagedDaemonInstructionRoot({
      projectId: DESKTOP_PROJECT_ID,
      packagedResourcesPath: process.resourcesPath,
      resolveProjectRoots: (projectId) => projects.roots(projectId)
    });
    process.env.CHIRALITY_INSTRUCTION_ROOT = resolution.instructionRoot;
    if (resolution.source === 'packaged-resources-fallback') {
      desktopLogger.warn('runtime.daemon.instruction_root.fallback', {
        instructionRoot: resolution.instructionRoot,
        reason: resolution.reason
      });
    } else {
      desktopLogger.info('runtime.daemon.instruction_root.resolved', {
        instructionRoot: resolution.instructionRoot,
        projectId: DESKTOP_PROJECT_ID,
        source: resolution.source
      });
    }
  } else {
    process.env.CHIRALITY_INSTRUCTION_ROOT = resolveInstructionRootForProcess();
  }
  desktopLogger.info('runtime.daemon.starting', {
    activationPolicy: resolveDaemonActivationPolicy(process.env),
    packaged: app.isPackaged,
    userData: app.getPath('userData'),
    pid: process.pid
  });
  runtimeHost = await startRuntimeHost();
  installRuntimeDaemonSignalShutdown({
    // Keep signal-driven shutdown inside the same Electron funnel as
    // before-quit, initialization failure, and daemon retirement. The facade
    // ultimately awaits the active host's RuntimeDaemon.stop() contract while
    // preserving the surrounding cleanup, logging, and app exit.
    stop: () => shutdown(0, 'runtime-daemon-signal')
  });
  desktopLogger.info('runtime.daemon.started', {
    socketPath: runtimeHost.socketPath,
    runtimeDirectory: runtimeHost.runtimeDirectory
  });
}

/**
 * Release everything this process owns, without exiting.
 *
 * Separate from `shutdown()` because the relaunch path must tear down and then
 * let Electron's *own* quit sequence finish: the helper that starts the
 * replacement process runs as part of that sequence, and `app.exit()` skips it.
 * Returns the exit code, raised to 1 if any teardown step failed.
 */
async function teardown(exitCode: number, reason: string): Promise<number> {
  if (shutdownStarted) {
    return exitCode;
  }
  shutdownStarted = true;
  // Logged first: the reason a daemon exited is exactly the evidence that was
  // missing when a clean `exit(0)` at GUI-launch time had to be diagnosed from
  // launchd bookkeeping alone.
  desktopLogger.info('desktop.shutdown.started', {
    reason,
    exitCode,
    daemonMode: runtimeDaemonMode,
    pid: process.pid
  });
  socketWatcher?.stop();
  socketWatcher = undefined;
  bindingSupervisor?.stop();
  bindingSupervisor = undefined;
  ipcMain.removeHandler('chirality:document-handoff');
  ipcMain.removeHandler(SELECT_DIRECTORY_CHANNEL);
  ipcMain.removeHandler(RUNTIME_CONNECTIVITY_QUERY_CHANNEL);
  unregisterApiKeyHandlers();
  unregisterRuntimeControlHandlers();

  if (runtimeHost) {
    try {
      await runtimeHost.stop();
    } catch (error) {
      exitCode = 1;
      desktopLogger.error('runtime.daemon.stop_failed', error);
    }
    runtimeHost = undefined;
  }

  if (rendererServer) {
    try {
      await rendererServer.close();
    } catch (error) {
      exitCode = 1;
      desktopLogger.error('desktop.renderer_server.close_failed', error);
    }
    rendererServer = undefined;
  }
  desktopLogger.info('desktop.shutdown.completed', { reason, exitCode });
  return exitCode;
}

async function shutdown(exitCode = 0, reason = 'unspecified'): Promise<void> {
  if (shutdownStarted) {
    return;
  }
  const finalExitCode = await teardown(exitCode, reason);
  shutdownCompleted = true;
  app.exit(finalExitCode);
}

app
  .whenReady()
  .then(async () => {
    if (runtimeDaemonMode) {
      await initializeDaemon();
      return;
    }
    await initializeGui();
  })
  .catch((error) => {
    desktopLogger.error(
      runtimeDaemonMode ? 'runtime.daemon.initialize_failed' : 'desktop.gui.initialize_failed',
      error instanceof Error ? error.message : String(error)
    );
    void shutdown(1, 'initialize-failed');
  });

app.on('window-all-closed', () => {
  if (!runtimeDaemonMode && process.platform !== 'darwin') {
    app.quit();
  }
});

// The single quit funnel for both modes.
//
// This deliberately no longer vetoes an initial quit in daemon mode. The old veto was built to
// refuse a quit AppleEvent thought to accompany a LaunchServices launch; three
// reproductions showed the daemon receives `activate` and *no* quit at all, so
// the veto never fired for its intended trigger — while it did swallow SIGTERM,
// because Chromium's own native signal handler runs before any JS handler and
// routes the signal into `app.quit()` -> `before-quit`. The result was a daemon
// that could only be stopped by force: `runtimeHost.stop()` ran on no exit path,
// every stop left a stale `control.sock`, and `launchctl bootout` took ~5 s to
// reach launchd's SIGKILL escalation.
//
// The stay-dead bug is covered by the restart contract alone: `KeepAlive <true/>`
// restarts the daemon after *any* exit, clean ones included. So a polite quit is
// now honoured and made graceful — stop the runtime host (releasing the control
// socket), then exit — and launchd brings the daemon straight back. A concurrent
// native quit is still vetoed while that teardown is in flight; only our final
// owned `app.exit()` is allowed through.
app.on('before-quit', (event) => {
  const hasOwnedResources = runtimeHost !== undefined || rendererServer !== undefined;
  if (
    shouldPreventNativeQuit({ shutdownStarted, shutdownCompleted, hasOwnedResources })
  ) {
    event.preventDefault();
    if (!shutdownStarted) {
      void shutdown(0, 'before-quit');
    }
  }
});

/**
 * Start the GUI from the daemon, in response to macOS resolving a bundle launch
 * against this headless process, then retire this daemon.
 *
 * `setActivationPolicy('prohibited')` removes the Dock tile and the menu bar but
 * does *not* remove the daemon as a LaunchServices resolution target: it stays
 * registered under `com.chirality.app` (reclassified `UIElement`), so a Finder
 * double-click or Dock click resolves to it, and because it has no window nothing
 * visible happens. Handling `activate` is what makes the app open again (V-D4).
 *
 * Why it also exits — the part that is not obvious. Forking from Chromium's
 * browser process leaves this process's signal handling broken: measured on the
 * packaged app, a daemon that had run one `child_process.spawn` stopped receiving
 * SIGTERM as `before-quit` at all, so `launchctl bootout` degraded to a 5.06 s
 * SIGKILL escalation with no graceful shutdown and a stale `control.sock`. A
 * control arm that received the same `activate` with the spawn suppressed stopped
 * in 0.034 s, gracefully. `app.relaunch()` avoids the fork but produced no GUI at
 * all here, so it is not an alternative.
 *
 * So: spawn the window, then immediately tear down and exit through our *own*
 * path, where no signal is involved and the broken handling cannot matter. The
 * fork-damaged process lives for milliseconds; launchd's `KeepAlive` then starts a
 * fresh daemon that has never forked and whose stop path is intact. The visible
 * cost is a bounded runtime reconnect (the GUI's supervisor rebinds on its own and
 * the top-bar chip shows it) instead of a daemon that cannot be stopped cleanly.
 *
 * The architecturally correct fix is for the daemon to carry its own bundle
 * identity so Finder never resolves to it at all — a packaging change, out of
 * scope here and escalated.
 */
function spawnGuiFromDaemon(): void {
  if (!isDaemonGuiSpawnEnabled(process.env)) {
    desktopLogger.info('runtime.daemon.gui_spawn_disabled');
    return;
  }
  const now = Date.now();
  if (now - lastGuiSpawnAt < GUI_SPAWN_MIN_INTERVAL_MS) {
    desktopLogger.info('runtime.daemon.gui_spawn_throttled', {
      sinceLastMs: now - lastGuiSpawnAt
    });
    return;
  }
  lastGuiSpawnAt = now;
  try {
    // `detached` puts the GUI in its own session so it outlives this daemon's
    // exit and launchd's job cleanup. No `--runtime-daemon`: the child is the GUI.
    // The environment carries over, which is what keeps an isolated run isolated.
    const child = spawn(app.getPath('exe'), [], { detached: true, stdio: 'ignore' });
    child.unref();
    desktopLogger.info('runtime.daemon.gui_spawned', { pid: child.pid });
  } catch (error) {
    desktopLogger.error('runtime.daemon.gui_spawn_failed', error);
    return;
  }
  // Retire this process now that it has forked; see the note above.
  void shutdown(0, 'retire-after-gui-spawn');
}

if (runtimeDaemonMode) {
  // `activate` in the daemon is the direct signature of macOS resolving a launch
  // of the app bundle against this headless instance instead of starting the GUI.
  app.on('activate', () => {
    desktopLogger.warn('runtime.daemon.activate_received', { pid: process.pid });
    spawnGuiFromDaemon();
  });
  app.on('open-file', (_event, filePath) => {
    desktopLogger.warn('runtime.daemon.open_file_received', { filePath });
  });
  app.on('open-url', () => {
    desktopLogger.warn('runtime.daemon.open_url_received', { pid: process.pid });
  });
  app.on('second-instance', () => {
    desktopLogger.warn('runtime.daemon.second_instance_received', { pid: process.pid });
  });
}

// GUI mode retains its direct Node signal path. Daemon mode instead installs
// the shared one-shot binder after the active RuntimeHost exists, so these
// listeners cannot race or duplicate its stop operation.
if (!runtimeDaemonMode) {
  for (const signal of ['SIGINT', 'SIGTERM'] as const) {
    process.once(signal, () => {
      void shutdown(signal === 'SIGINT' ? 130 : 0, `signal:${signal}`);
    });
  }
}

import { contextBridge, ipcRenderer } from 'electron';
import {
  RUNTIME_CONNECTIVITY_CHANGED_CHANNEL,
  RUNTIME_CONNECTIVITY_QUERY_CHANNEL,
  type RuntimeConnectivitySnapshot
} from './runtime-connectivity';

const SELECT_DIRECTORY_CHANNEL = 'chirality:select-directory';
const API_KEY_STORE_CHANNEL = 'chirality:api-key-store';
const API_KEY_REMOVE_CHANNEL = 'chirality:api-key-remove';
const API_KEY_STATUS_CHANNEL = 'chirality:api-key-status';
const PROVIDER_API_KEY_STORE_CHANNEL = 'chirality:provider-api-key-store';
const PROVIDER_API_KEY_REMOVE_CHANNEL = 'chirality:provider-api-key-remove';
const PROVIDER_API_KEY_STATUS_CHANNEL = 'chirality:provider-api-key-status';
const RUNTIME_DAEMON_CONTROL_CHANNEL = 'chirality:runtime-daemon-control';
const RUNTIME_MODEL_STATUS_CHANNEL = 'chirality:runtime-model-status';
const RUNTIME_MODEL_ACTIVATE_CHANNEL = 'chirality:runtime-model-activate';

contextBridge.exposeInMainWorld('chirality', {
  platform: process.platform,
  versions: {
    chrome: process.versions.chrome,
    electron: process.versions.electron,
    node: process.versions.node
  },
  selectDirectory: () => ipcRenderer.invoke(SELECT_DIRECTORY_CHANNEL),
  document: {
    // Both Electron modes retain the current frame-denying renderer policy.
    inlinePdfPreview: false,
    handoff: (request: { projectRoot: string; target: string; action: 'quick-look' | 'open' }) =>
      ipcRenderer.invoke('chirality:document-handoff', request)
  },
  apiKey: {
    store: (key: string) => ipcRenderer.invoke(API_KEY_STORE_CHANNEL, key),
    remove: () => ipcRenderer.invoke(API_KEY_REMOVE_CHANNEL),
    status: () => ipcRenderer.invoke(API_KEY_STATUS_CHANNEL)
  },
  providerApiKey: {
    store: (providerId: 'anthropic' | 'omlx', key: string) =>
      ipcRenderer.invoke(PROVIDER_API_KEY_STORE_CHANNEL, providerId, key),
    remove: (providerId: 'anthropic' | 'omlx') =>
      ipcRenderer.invoke(PROVIDER_API_KEY_REMOVE_CHANNEL, providerId),
    status: (providerId: 'anthropic' | 'omlx') =>
      ipcRenderer.invoke(PROVIDER_API_KEY_STATUS_CHANNEL, providerId)
  },
  runtime: {
    /**
     * Runtime-daemon connectivity as the main process sees it. `get()` is for
     * mount-time hydration; `subscribe()` receives every later transition so the
     * top bar reflects a daemon that dies or returns without the renderer
     * polling. The unsubscribe function must be called on unmount — the listener
     * is held by `ipcRenderer`, which outlives any React tree.
     */
    connectivity: {
      get: (): Promise<RuntimeConnectivitySnapshot | null> =>
        ipcRenderer.invoke(RUNTIME_CONNECTIVITY_QUERY_CHANNEL),
      subscribe: (listener: (snapshot: RuntimeConnectivitySnapshot) => void): (() => void) => {
        const handler = (_event: unknown, snapshot: RuntimeConnectivitySnapshot): void => {
          listener(snapshot);
        };
        ipcRenderer.on(RUNTIME_CONNECTIVITY_CHANGED_CHANNEL, handler);
        return () => {
          ipcRenderer.removeListener(RUNTIME_CONNECTIVITY_CHANGED_CHANNEL, handler);
        };
      }
    },
    daemon: {
      install: () => ipcRenderer.invoke(RUNTIME_DAEMON_CONTROL_CHANNEL, 'install'),
      start: () => ipcRenderer.invoke(RUNTIME_DAEMON_CONTROL_CHANNEL, 'start'),
      stop: () => ipcRenderer.invoke(RUNTIME_DAEMON_CONTROL_CHANNEL, 'stop'),
      status: () => ipcRenderer.invoke(RUNTIME_DAEMON_CONTROL_CHANNEL, 'status'),
      uninstall: () => ipcRenderer.invoke(RUNTIME_DAEMON_CONTROL_CHANNEL, 'uninstall')
    },
    models: {
      status: () => ipcRenderer.invoke(RUNTIME_MODEL_STATUS_CHANNEL),
      activate: (modelId: string) =>
        ipcRenderer.invoke(RUNTIME_MODEL_ACTIVATE_CHANNEL, modelId)
    }
  }
});

import { randomBytes } from 'node:crypto';

/**
 * Renderer window hardening policy (DEL-09-06-V3-01, G-CSP).
 *
 * Pure policy functions (testable without Electron) plus one installer applied
 * to every BrowserWindow the main process creates:
 *
 * - web preferences are asserted at creation: `contextIsolation: true`,
 *   `nodeIntegration: false`, `sandbox: true`; anything else fails closed;
 * - `setWindowOpenHandler` never lets the renderer create a child
 *   BrowserWindow. The renderer *does* ask for windows — every link in rendered
 *   chat markdown (`src/components/shell/chat-markdown.tsx`) and the
 *   navigator's "open legacy interface" link (`src/components/woven-dialogue/
 *   navigator.tsx`) use `target="_blank"` — so an `http:`/`https:` target is
 *   handed to the operating system's default browser (`shell.openExternal`,
 *   injected by `main.ts`) instead of a child window that would inherit this
 *   app's preload and IPC bridge; every other scheme is dropped. Before this
 *   policy such a click created a child BrowserWindow at the link's URL; now it
 *   opens the system browser (coordinator decision 2026-09-03, recorded in the
 *   run record). This is not app egress: nothing leaves this process.
 * - `will-navigate` and `will-redirect` allow only the app's own renderer
 *   origin over http(s) and deny everything else — `javascript:`, `file:`,
 *   `data:`, `about:`, `blob:`, foreign hosts, a different port or scheme;
 * - the packaged server creates a fresh nonce and one policy per request,
 *   presents that policy to Next before rendering, and returns the exact same
 *   policy on the response; the response hook never fabricates a packaged
 *   fallback whose nonce could disagree with the rendered document;
 * - development keeps its static policy fallback through
 *   `webRequest.onHeadersReceived`, including the allowances Next dev needs.
 *
 * The CSP is defence in depth beside the REQ-NET-001 egress allowlist in
 * `main.ts`, not a replacement for it: the egress layer is what the packaged
 * proof observes on the wire, through the main-process probe below.
 */

export type RendererWindowLog = (
  level: 'info' | 'warn' | 'error',
  event: string,
  detail?: unknown
) => void;

export const REQUIRED_RENDERER_WEB_PREFERENCES = Object.freeze({
  contextIsolation: true,
  nodeIntegration: false,
  sandbox: true
} as const);

const FORBIDDEN_RENDERER_WEB_PREFERENCES = [
  'nodeIntegrationInWorker',
  'nodeIntegrationInSubFrames',
  'webviewTag',
  'allowRunningInsecureContent',
  'enableRemoteModule',
  'experimentalFeatures'
] as const;

export type RendererWebPreferencesInput = Record<string, unknown>;

/** Throws when the preferences would weaken the renderer boundary. */
export function assertRendererWebPreferences(preferences: RendererWebPreferencesInput): void {
  const problems: string[] = [];
  if (preferences.contextIsolation !== true) problems.push('contextIsolation must be true');
  if (preferences.nodeIntegration !== false) problems.push('nodeIntegration must be false');
  if (preferences.sandbox !== true) problems.push('sandbox must be true');
  if (preferences.webSecurity === false) problems.push('webSecurity must not be disabled');
  for (const name of FORBIDDEN_RENDERER_WEB_PREFERENCES) {
    if (preferences[name] === true) problems.push(`${name} must not be enabled`);
  }
  if (problems.length > 0) {
    throw new Error(
      `Renderer window web preferences violate the hardening policy: ${problems.join('; ')}`
    );
  }
}

export type RendererWebPreferences = {
  preload: string;
  contextIsolation: true;
  nodeIntegration: false;
  sandbox: true;
};

/** The only web preferences a renderer window may be created with. */
export function rendererWebPreferences(input: { preload: string }): RendererWebPreferences {
  const preferences: RendererWebPreferences = {
    preload: input.preload,
    ...REQUIRED_RENDERER_WEB_PREFERENCES
  };
  assertRendererWebPreferences(preferences);
  return preferences;
}

export type RendererNavigationDecision =
  | { allowed: true }
  | { allowed: false; reason: 'INVALID_URL' | 'SCHEME_NOT_HTTP' | 'ORIGIN_NOT_RENDERER' };

/**
 * Renderer-initiated navigations may target only the renderer origin itself,
 * over http(s). The scheme check comes first because a `blob:` URL reports its
 * creator's origin — equal to the renderer's — while `javascript:`, `file:`,
 * `data:` and `about:` report the opaque origin `null`; none of them is a page
 * of the app. Everything at a foreign origin, port, or scheme is denied.
 */
export function evaluateRendererNavigation(
  rawUrl: string,
  rendererOrigin: string
): RendererNavigationDecision {
  let parsed: URL;
  try {
    parsed = new URL(rawUrl);
  } catch {
    return { allowed: false, reason: 'INVALID_URL' };
  }
  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
    return { allowed: false, reason: 'SCHEME_NOT_HTTP' };
  }
  if (!rendererOrigin || parsed.origin === 'null' || parsed.origin !== rendererOrigin) {
    return { allowed: false, reason: 'ORIGIN_NOT_RENDERER' };
  }
  return { allowed: true };
}

export type WindowOpenDecision =
  | { action: 'deny'; external: true }
  | { action: 'deny'; external: false; reason: 'INVALID_URL' | 'SCHEME_NOT_HTTP' };

/**
 * A child BrowserWindow is never created (`action: 'deny'` for every request).
 * An `http:`/`https:` target is instead opened in the system browser by the
 * installer; a malformed URL or any other scheme (`javascript:`, `file:`,
 * `data:`, `blob:`, `about:`, custom) is dropped.
 */
export function evaluateWindowOpen(details: { url: string }): WindowOpenDecision {
  let parsed: URL;
  try {
    parsed = new URL(details.url);
  } catch {
    return { action: 'deny', external: false, reason: 'INVALID_URL' };
  }
  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
    return { action: 'deny', external: false, reason: 'SCHEME_NOT_HTTP' };
  }
  return { action: 'deny', external: true };
}

export type RendererCspMode = 'packaged' | 'development';

const RENDERER_CSP_NONCE_BYTES = 16;
const RENDERER_CSP_NONCE_PATTERN = /^[A-Za-z0-9+/_-]+={0,2}$/;

/** A 128-bit, request-local nonce in the alphabet accepted by pinned Next. */
export function createRendererCspNonce(): string {
  return randomBytes(RENDERER_CSP_NONCE_BYTES).toString('base64');
}

function assertRendererCspNonce(nonce: string | undefined): asserts nonce is string {
  if (!nonce || !RENDERER_CSP_NONCE_PATTERN.test(nonce)) {
    throw new Error('Packaged renderer CSP requires a valid request nonce');
  }
}

/**
 * Renderer Content-Security-Policy.
 *
 * What the renderer actually needs, verified against the `npm run build` output
 * and the dev server (recorded in the DEL-09-06 evidence):
 * - packaged `script-src` uses the request nonce and never `'unsafe-inline'` or
 *   `'unsafe-eval'`. The custom server gives the same policy to Next before it
 *   renders, so Next's inline flight scripts carry the nonce. The root layout
 *   reads the same request policy for the app-owned theme bootstrap. External
 *   scripts remain restricted to `'self'`.
 * - development retains `'unsafe-inline'` and `'unsafe-eval'`: Next's dev
 *   runtime and React Refresh require them. No development posture changes.
 * - `'unsafe-eval'` only in development: Next's dev runtime and React Refresh
 *   evaluate source; the packaged renderer never gets it.
 * - `style-src 'unsafe-inline'`: two components set React `style` props (inline
 *   style attributes) and Next injects style elements in development.
 * - `connect-src 'self'` in packaged mode: the renderer talks only to its own
 *   Next server; the Anthropic and oMLX calls are made server-side by the Next
 *   server process and the daemon, never by the page. This is stricter than the
 *   REQ-NET-001 egress allowlist, which stays as the wire-level backstop. The
 *   dev server's HMR WebSocket needs the `ws:`/`wss:` form of its own origin.
 * - everything else is closed: no frames, no plugins, no foreign forms or bases,
 *   no embedding.
 */
export function buildRendererContentSecurityPolicy(options: {
  mode: RendererCspMode;
  rendererOrigin?: string;
  nonce?: string;
}): string {
  const development = options.mode === 'development';
  if (!development) {
    assertRendererCspNonce(options.nonce);
  }
  const connectSources = ["'self'"];
  if (development && options.rendererOrigin) {
    try {
      const origin = new URL(options.rendererOrigin);
      connectSources.push(`ws://${origin.host}`, `wss://${origin.host}`);
    } catch {
      // An unparseable origin adds nothing; 'self' still covers same-origin.
    }
  }
  const directives = [
    "default-src 'self'",
    development
      ? "script-src 'self' 'unsafe-inline' 'unsafe-eval'"
      : `script-src 'self' 'nonce-${options.nonce}'`,
    "style-src 'self' 'unsafe-inline'",
    "img-src 'self' data:",
    "font-src 'self' data:",
    `connect-src ${connectSources.join(' ')}`,
    "worker-src 'self'",
    "manifest-src 'self'",
    "media-src 'self'",
    "frame-src 'none'",
    "object-src 'none'",
    "base-uri 'self'",
    "form-action 'self'",
    "frame-ancestors 'none'"
  ];
  return directives.join('; ');
}

export const CONTENT_SECURITY_POLICY_HEADER = 'Content-Security-Policy';

type RendererRequestHeaders = Record<string, string | string[] | undefined>;
type RendererResponseHeaderSink = { setHeader(name: string, value: string): unknown };

/**
 * Establish the packaged renderer's one-policy invariant before Next handles a
 * request. The policy is derived once and assigned byte-for-byte to both the
 * incoming request and outgoing response. Next 15.5 reads the request CSP and
 * applies its nonce to framework scripts; the app layout reads that same CSP
 * for its own inline bootstrap. There is no second nonce-bearing header that
 * could disagree with the enforced policy.
 */
export function applyPackagedRendererRequestPolicy(
  request: { headers: RendererRequestHeaders },
  response: RendererResponseHeaderSink,
  nonce: string = createRendererCspNonce()
): { nonce: string; contentSecurityPolicy: string } {
  assertRendererCspNonce(nonce);
  const contentSecurityPolicy = buildRendererContentSecurityPolicy({ mode: 'packaged', nonce });
  request.headers[CONTENT_SECURITY_POLICY_HEADER.toLowerCase()] = contentSecurityPolicy;
  response.setHeader(CONTENT_SECURITY_POLICY_HEADER, contentSecurityPolicy);
  return { nonce, contentSecurityPolicy };
}

type ResponseHeaders = Record<string, string[]>;

function hasContentSecurityPolicy(headers: ResponseHeaders): boolean {
  return Object.keys(headers).some(
    (name) => name.toLowerCase() === CONTENT_SECURITY_POLICY_HEADER.toLowerCase()
  );
}

/**
 * Headers to install on a response from the renderer origin that carries no
 * policy, or `null` when the response must be left exactly as received (foreign
 * origin, unparseable URL, or a policy already present). Pure.
 */
export function applyContentSecurityPolicyHeader(
  details: { url: string; responseHeaders?: ResponseHeaders },
  rendererOrigin: string,
  contentSecurityPolicy: string
): ResponseHeaders | null {
  let origin: string;
  try {
    origin = new URL(details.url).origin;
  } catch {
    return null;
  }
  const headers = details.responseHeaders ?? {};
  if (origin !== rendererOrigin || hasContentSecurityPolicy(headers)) {
    return null;
  }
  return { ...headers, [CONTENT_SECURITY_POLICY_HEADER]: [contentSecurityPolicy] };
}

/** Non-secret destination summary for diagnostics: no path, query, or userinfo. */
export function summarizeDestination(rawUrl: string): { protocol: string; hostname: string } | null {
  try {
    const parsed = new URL(rawUrl);
    return { protocol: parsed.protocol, hostname: parsed.hostname };
  } catch {
    return null;
  }
}

export type RendererWindowLike = {
  webContents: {
    setWindowOpenHandler(handler: (details: { url: string }) => { action: 'deny' }): void;
    on(
      event: 'will-navigate' | 'will-redirect',
      listener: (event: { preventDefault(): void }, url: string) => void
    ): unknown;
    session: {
      webRequest: {
        onHeadersReceived(
          filter: { urls: string[] },
          listener: (
            details: { url: string; responseHeaders?: ResponseHeaders },
            callback: (response: { responseHeaders?: ResponseHeaders }) => void
          ) => void
        ): void;
      };
    };
  };
};

export type RendererWindowPolicyOptions = {
  rendererOrigin: string;
  /** Development-only fallback. Packaged responses must carry their request nonce. */
  contentSecurityPolicy?: string;
  /** Opens an `http(s)` URL in the operating system's default browser. */
  openExternal: (url: string) => Promise<void>;
  log?: RendererWindowLog;
};

const HEADER_FILTER_URLS = ['http://*/*', 'https://*/*'];

/** Install window-open handling, navigation containment, and the CSP on one window. */
export function installRendererWindowPolicy(
  window: RendererWindowLike,
  options: RendererWindowPolicyOptions
): void {
  const { rendererOrigin, contentSecurityPolicy, openExternal, log } = options;
  const { webContents } = window;

  webContents.setWindowOpenHandler((details) => {
    const decision = evaluateWindowOpen(details);
    const destination = summarizeDestination(details.url);
    if (decision.external) {
      log?.('info', 'renderer.window_open.external_opened', { destination });
      // Deferred so a synchronous throw from the injected opener is caught the
      // same way as a rejection and can never escape the handler.
      Promise.resolve()
        .then(() => openExternal(details.url))
        .catch((error: unknown) => {
          log?.('warn', 'renderer.window_open.external_failed', {
            destination,
            error: error instanceof Error ? error.message : String(error)
          });
        });
    } else {
      log?.('warn', 'renderer.window_open.denied', { reason: decision.reason, destination });
    }
    return { action: 'deny' };
  });

  for (const eventName of ['will-navigate', 'will-redirect'] as const) {
    webContents.on(eventName, (event, url) => {
      const decision = evaluateRendererNavigation(url, rendererOrigin);
      if (decision.allowed) {
        return;
      }
      event.preventDefault();
      log?.('warn', 'renderer.navigation.denied', {
        event: eventName,
        reason: decision.reason,
        destination: summarizeDestination(url)
      });
    });
  }

  webContents.session.webRequest.onHeadersReceived(
    { urls: HEADER_FILTER_URLS },
    (details, callback) => {
      const responseHeaders = contentSecurityPolicy
        ? applyContentSecurityPolicyHeader(details, rendererOrigin, contentSecurityPolicy)
        : null;
      // No override at all when untouched: echoing an empty header set would
      // tell Chromium the server answered with no headers.
      callback(responseHeaders === null ? {} : { responseHeaders });
    }
  );
}

type ProbeEnvironment = Record<string, string | undefined>;

function probeDelayMs(env: ProbeEnvironment, fallback: number): number {
  const parsed = Number.parseInt(env.CHIRALITY_RENDERER_SECURITY_PROBE_DELAY_MS ?? '', 10);
  return Number.isSafeInteger(parsed) && parsed > 0 ? parsed : fallback;
}

function afterLoad(
  webContents: { isLoadingMainFrame(): boolean; once(event: 'did-finish-load', listener: () => void): unknown },
  delayMs: number,
  run: () => void
): void {
  const schedule = (): void => {
    setTimeout(run, delayMs);
  };
  if (webContents.isLoadingMainFrame()) {
    webContents.once('did-finish-load', schedule);
  } else {
    schedule();
  }
}

/**
 * Optional in-page probe for the packaged security proof
 * (`CHIRALITY_RENDERER_SECURITY_PROBE=1`): reports the document's CSP header
 * (same-origin fetch of the page), a denied `window.open` — deliberately of an
 * `about:blank` target so the proof never opens the host's browser; the
 * `http(s)` hand-off is unit-tested — the `securitypolicyviolation` events
 * raised by a deliberately blocked fetch, and finally attempts a foreign
 * navigation so the main process logs its denial. Nothing runs unless the
 * environment asks for it. Results are written to the console under the
 * `[renderer-security-probe]` marker the proof reads.
 */
export function runRendererSecurityProbe(
  window: {
    webContents: {
      isLoadingMainFrame(): boolean;
      once(event: 'did-finish-load', listener: () => void): unknown;
      executeJavaScript(code: string, userGesture?: boolean): Promise<unknown>;
    };
  },
  options: { env: ProbeEnvironment }
): void {
  if (options.env.CHIRALITY_RENDERER_SECURITY_PROBE !== '1') {
    return;
  }
  const script = `
(() => {
  const violations = [];
  const noncePattern = /^[A-Za-z0-9+/_-]+={0,2}$/;
  const nonceFromPolicy = (policy) => {
    if (typeof policy !== 'string') return null;
    const scriptDirective = policy
      .split(';')
      .map((directive) => directive.trim())
      .find((directive) => directive.startsWith('script-src '));
    if (!scriptDirective) return null;
    for (const source of scriptDirective.split(/\\s+/).slice(1)) {
      const match = source.match(/^'nonce-([A-Za-z0-9+/_-]+={0,2})'$/);
      if (match) return match[1];
    }
    return null;
  };
  const inlineScriptNonces = (root) => Array.from(root.querySelectorAll('script'))
    .filter((node) => !node.src && (node.textContent || '').trim().length > 0)
    .map((node) => node.nonce || null);
  const inspectResponse = async () => {
    const response = await fetch(location.href, { cache: 'no-store' });
    const cspHeader = response.headers.get('content-security-policy');
    const html = await response.text();
    const responseNonce = nonceFromPolicy(cspHeader);
    const parsed = new DOMParser().parseFromString(html, 'text/html');
    const scriptNonces = inlineScriptNonces(parsed);
    return {
      status: response.status,
      contentType: response.headers.get('content-type'),
      cspHeader,
      responseNonce,
      inlineScriptCount: scriptNonces.length,
      inlineScriptNoncesMatch: scriptNonces.length > 0 &&
        scriptNonces.every((value) => value === responseNonce),
      documentComplete: html.includes('</html>')
    };
  };
  document.addEventListener('securitypolicyviolation', (event) => {
    violations.push({
      blockedURI: event.blockedURI,
      effectiveDirective: event.effectiveDirective,
      disposition: event.disposition
    });
  });
  const run = async () => {
    const documentScriptNonces = inlineScriptNonces(document);
    const documentNonce = documentScriptNonces.find((value) => noncePattern.test(value || '')) || null;
    let consecutiveResponses = [];
    let responseError = null;
    try {
      consecutiveResponses = [await inspectResponse(), await inspectResponse()];
    } catch (error) {
      responseError = error instanceof Error ? error.message : String(error);
    }
    let windowOpen;
    try {
      const opened = window.open('about:blank#chirality-renderer-security-window-open', '_blank');
      windowOpen = { returned: opened === null ? 'null' : typeof opened };
    } catch (error) {
      windowOpen = { error: error instanceof Error ? error.message : String(error) };
    }
    try {
      await fetch('https://example.com/chirality-renderer-security-csp-blocked', {
        mode: 'no-cors',
        cache: 'no-store'
      });
    } catch {
      // A rejected fetch is the expected outcome; the violation event is the evidence.
    }
    await new Promise((resolve) => setTimeout(resolve, 250));
    const navigationTarget = 'https://example.com/chirality-renderer-security-navigation';
    setTimeout(() => {
      try {
        location.assign(navigationTarget);
      } catch {
        // Denied navigation surfaces in the main-process log.
      }
    }, 0);
    return {
      policy: 'G-CSP',
      route: location.pathname,
      documentNonce: noncePattern.test(documentNonce || '') ? documentNonce : null,
      documentInlineScriptCount: documentScriptNonces.length,
      documentInlineScriptNoncesMatch: documentScriptNonces.length > 0 &&
        documentScriptNonces.every((value) => value === documentNonce),
      consecutiveResponses,
      responseError,
      windowOpen,
      violations,
      navigationAttempted: navigationTarget
    };
  };
  return run();
})();
`;
  afterLoad(window.webContents, probeDelayMs(options.env, 1500), () => {
    void window.webContents
      .executeJavaScript(script, true)
      .then((result) => {
        console.info('[renderer-security-probe]', JSON.stringify(result));
      })
      .catch((error: unknown) => {
        console.error(
          '[renderer-security-probe]',
          JSON.stringify({ policy: 'G-CSP', error: error instanceof Error ? error.message : String(error) })
        );
      });
  });
}

/**
 * The one destination the main-process egress-layer probe may request. It is
 * fixed here and never read from the environment or taken from a caller, so
 * nothing outside this module can point the probe at a destination the
 * REQ-NET-001 egress policy in `main.ts` would allow (DEL-09-06-V3-05). The
 * Anthropic API host is allowlisted only over `https:` on port 443, so the same
 * host on port 8443 is denied by the policy's port rule
 * (`anthropic_port_not_allowlisted:8443`) — exactly the denial the packaged
 * proof counts. The proof script carries the same literal as its expectation
 * and its unit test checks the two stay byte-equal.
 */
export const EGRESS_LAYER_PROBE_URL =
  'https://api.anthropic.com:8443/chirality-packaged-security-egress-blocked';

/**
 * Optional main-process probe of the REQ-NET-001 egress layer for the packaged
 * security proof (same gate as the in-page probe; the destination is
 * `EGRESS_LAYER_PROBE_URL`, always). The page cannot reach the egress layer for
 * a foreign host any more — the CSP stops it first — so the proof issues the
 * request from the main process through the window's session: `session.fetch`
 * goes through `webRequest`, where `onBeforeRequest` cancels it and logs the
 * denial. A rejected fetch is the expected outcome; a response would mean the
 * egress layer let it through. The logged destination carries protocol,
 * hostname, and port (the port is what makes it a denied destination) and no
 * path.
 */
export function runEgressLayerProbe(
  window: {
    webContents: {
      isLoadingMainFrame(): boolean;
      once(event: 'did-finish-load', listener: () => void): unknown;
      session: {
        fetch(
          input: string,
          init?: { method?: string; cache?: 'no-store'; signal?: AbortSignal }
        ): Promise<{ status: number }>;
      };
    };
  },
  options: { env: ProbeEnvironment }
): void {
  if (options.env.CHIRALITY_RENDERER_SECURITY_PROBE !== '1') {
    return;
  }
  const parsed = new URL(EGRESS_LAYER_PROBE_URL);
  const destination = { protocol: parsed.protocol, hostname: parsed.hostname, port: parsed.port };
  afterLoad(window.webContents, probeDelayMs(options.env, 1500) + 500, () => {
    void window.webContents.session
      .fetch(EGRESS_LAYER_PROBE_URL, {
        method: 'GET',
        cache: 'no-store',
        signal: AbortSignal.timeout(3000)
      })
      .then((response) => {
        console.info(
          '[egress-layer-probe]',
          JSON.stringify({ policy: 'REQ-NET-001', destination, outcome: 'response', status: response.status })
        );
      })
      .catch((error: unknown) => {
        console.info(
          '[egress-layer-probe]',
          JSON.stringify({
            policy: 'REQ-NET-001',
            destination,
            outcome: 'rejected',
            error: error instanceof Error ? error.message : String(error)
          })
        );
      });
  });
}

#!/usr/bin/env node

import { spawn } from 'node:child_process';
import { createHash, randomUUID } from 'node:crypto';
import { createWriteStream } from 'node:fs';
import {
  access,
  chmod,
  mkdir,
  mkdtemp,
  readFile,
  readdir,
  realpath,
  rm,
  stat,
  writeFile
} from 'node:fs/promises';
import path from 'node:path';
import process from 'node:process';
import { fileURLToPath } from 'node:url';
import { RuntimeClient } from '@chirality/runtime-client';

const SCRIPT_PATH = fileURLToPath(import.meta.url);
const FRONTEND_ROOT = path.resolve(path.dirname(SCRIPT_PATH), '..');
const DEFAULT_APP_PATH = path.join(FRONTEND_ROOT, 'dist', 'mac-arm64', 'Chirality.app');
const DEFAULT_OUTPUT_ROOT = path.join(
  FRONTEND_ROOT,
  'artifacts',
  'release-verification',
  'packaged-security'
);
const ASAR_CLI = path.join(FRONTEND_ROOT, 'node_modules', '.bin', 'asar');
const LOOPBACK_HOSTS = new Set(['localhost', '127.0.0.1', '::1', '[::1]']);
const PACKAGED_POLICY_MARKERS = [
  'REQ-NET-001',
  'api.anthropic.com',
  'anthropic_protocol_not_allowlisted',
  'anthropic_port_not_allowlisted',
  'host_not_allowlisted',
  'Blocked renderer outbound request by network policy',
  'Attachment exceeds per-file size limit',
  'Attachment exceeds per-turn size budget',
  'symbolic links are rejected',
  'ATTACHMENT_FAILURE',
  'Content-Security-Policy',
  'renderer.window_open.denied',
  'renderer.navigation.denied'
];
const BLOCKED_PROBE_URL = 'https://example.com/chirality-packaged-security-blocked';
const LOOPBACK_PROBE_URL = 'http://127.0.0.1:9/chirality-packaged-security-loopback';
export const PACKAGED_RENDERER_ROUTES = ['/', '/chat', '/pipeline', '/workbench'];
// The page can no longer reach the REQ-NET-001 egress layer for a foreign host
// (the CSP's connect-src 'self' stops it first), so the packaged app issues this
// request itself, from the main process through the window's session, where
// onBeforeRequest denies it (anthropic_port_not_allowlisted:8443). The
// destination is fixed inside the app (renderer-window-policy.ts
// EGRESS_LAYER_PROBE_URL) and is never read from the environment, so this proof
// cannot point the probe anywhere else (DEL-09-06-V3-05); the constant below is
// what the summarizer expects to observe, and the unit test checks it is
// byte-equal to the app's. The example.com probe above is the CSP-layer
// observation.
export const EGRESS_PROBE_URL = 'https://api.anthropic.com:8443/chirality-packaged-security-egress-blocked';
const EGRESS_PROBE_DESTINATION = new URL(EGRESS_PROBE_URL);
// Negative control: the retired probe-URL variable is set to a destination the
// egress policy WOULD allow (loopback; port 9 refuses the connection, so nothing
// leaves the host). The app must ignore it: the only probe payload observed must
// still name the :8443 destination, and any other destination fails the proof.
export const EGRESS_PROBE_DECOY_URL = 'http://127.0.0.1:9/chirality-packaged-security-egress-probe-decoy';

function nowIso() {
  return new Date().toISOString();
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function readArgValue(argv, index, flagName) {
  const value = argv[index];
  if (!value || value.startsWith('--')) throw new Error(`Missing value for ${flagName}`);
  return value;
}

export function parseArgs(argv) {
  const options = {};
  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];
    if (token === '--app-path') {
      options.appPath = readArgValue(argv, index + 1, token);
      index += 1;
    } else if (token === '--output-root') {
      options.outputRoot = readArgValue(argv, index + 1, token);
      index += 1;
    } else if (token === '--source-revision') {
      options.sourceRevision = readArgValue(argv, index + 1, token);
      index += 1;
    } else if (token === '--capture-seconds') {
      const parsed = Number.parseInt(readArgValue(argv, index + 1, token), 10);
      if (!Number.isSafeInteger(parsed) || parsed < 3 || parsed > 120) {
        throw new Error('--capture-seconds must be an integer from 3 through 120');
      }
      options.captureSeconds = parsed;
      index += 1;
    } else if (token === '--help') {
      options.help = true;
    } else {
      throw new Error(`Unknown argument: ${token}`);
    }
  }
  return {
    appPath: path.resolve(options.appPath ?? DEFAULT_APP_PATH),
    outputRoot: path.resolve(options.outputRoot ?? DEFAULT_OUTPUT_ROOT),
    sourceRevision: options.sourceRevision,
    captureSeconds: options.captureSeconds ?? 12,
    help: options.help === true
  };
}

function usage() {
  return `Usage: node ./scripts/run-packaged-security-proof.mjs [options]\n\nOptions:\n  --app-path <path>         Freshly built Chirality.app\n  --output-root <path>      Retained proof directory\n  --source-revision <sha>   Expected Git HEAD (default: current HEAD)\n  --capture-seconds <n>     Packaged network capture window (default: 12)\n  --help                    Show this message\n`;
}

async function runCommand(command, args, options = {}) {
  return new Promise((resolve, reject) => {
    const child = spawn(command, args, {
      cwd: options.cwd,
      env: options.env,
      stdio: ['ignore', 'pipe', 'pipe']
    });
    let stdout = '';
    let stderr = '';
    child.stdout.on('data', (chunk) => { stdout += chunk.toString(); });
    child.stderr.on('data', (chunk) => { stderr += chunk.toString(); });
    child.once('error', reject);
    child.once('close', (code, signal) => resolve({ code: code ?? 1, signal, stdout, stderr }));
  });
}

async function sha256File(filePath) {
  return createHash('sha256').update(await readFile(filePath)).digest('hex');
}

async function captureAppIdentity(appPath, sourceRevision) {
  const canonicalAppPath = await realpath(appPath);
  const relativeFiles = [
    'Contents/MacOS/Chirality',
    'Contents/Resources/app.asar',
    'Contents/Resources/runtime-cli/chirality-cli.mjs'
  ];
  const files = [];
  for (const relativePath of relativeFiles) {
    const absolutePath = await realpath(path.join(canonicalAppPath, relativePath));
    const metadata = await stat(absolutePath);
    if (!metadata.isFile()) throw new Error(`Packaged identity target is not a file: ${absolutePath}`);
    files.push({ relativePath, bytes: metadata.size, sha256: await sha256File(absolutePath) });
  }
  const identityBasis = JSON.stringify({ sourceRevision, files });
  return {
    schema: 'chirality-packaged-security-subject/v1',
    appPath: canonicalAppPath,
    sourceRevision,
    files,
    identitySha256: createHash('sha256').update(identityBasis).digest('hex')
  };
}

async function extractPackagedMain(appPath, extractionRoot) {
  const asarPath = path.join(appPath, 'Contents', 'Resources', 'app.asar');
  await access(ASAR_CLI);
  const result = await runCommand(ASAR_CLI, ['extract-file', asarPath, 'dist-electron/main.js'], {
    cwd: extractionRoot
  });
  if (result.code !== 0) {
    throw new Error(`asar extract-file failed (${result.code}): ${result.stderr.trim()}`);
  }
  return readFile(path.join(extractionRoot, 'main.js'), 'utf8');
}

export function inspectPackagedPolicyMarkers(packagedMain) {
  const markers = PACKAGED_POLICY_MARKERS.map((marker) => ({
    marker,
    present: packagedMain.includes(marker)
  }));
  return {
    markers,
    allPresent: markers.every((entry) => entry.present)
  };
}

function startLoggedProcess({ label, command, args, env, logPath }) {
  const child = spawn(command, args, {
    cwd: FRONTEND_ROOT,
    env,
    stdio: ['ignore', 'pipe', 'pipe']
  });
  // Truncate, never append: every log-derived observation below must come from
  // this run alone, or a stale file from an earlier run could satisfy a check
  // the current bundle did not.
  const stream = createWriteStream(logPath, { flags: 'w', mode: 0o600 });
  let captured = '';
  const append = (chunk) => {
    const text = chunk.toString();
    captured += text;
    stream.write(text);
  };
  stream.write(`[${nowIso()}] START ${label}: ${command} ${args.join(' ')}\n`);
  child.stdout.on('data', append);
  child.stderr.on('data', append);
  const closed = new Promise((resolve) => {
    child.once('close', (code, signal) => {
      stream.write(`[${nowIso()}] EXIT ${label}: code=${code ?? 'null'} signal=${signal ?? 'null'}\n`);
      resolve({ code, signal });
    });
  });
  return { child, stream, closed, captured: () => captured };
}

async function stopProcess(processRecord, label) {
  const child = processRecord?.child;
  if (!child) {
    return { label, started: false, confirmedStopped: false, streamClosed: false };
  }

  const isStopped = () => child.exitCode !== null || child.signalCode !== null;
  let signalSent = null;
  if (!isStopped()) {
    signalSent = 'SIGTERM';
    child.kill('SIGTERM');
  }
  const deadline = Date.now() + 10_000;
  while (!isStopped() && Date.now() < deadline) await sleep(100);
  if (!isStopped()) {
    signalSent = 'SIGKILL';
    child.kill('SIGKILL');
    const killDeadline = Date.now() + 2_000;
    while (!isStopped() && Date.now() < killDeadline) await sleep(100);
  }
  if (isStopped()) await processRecord.closed;
  const streamClosed = await new Promise((resolve) => {
    processRecord.stream.end(() => resolve(true));
    processRecord.stream.once('error', () => resolve(false));
  });
  return {
    label,
    started: true,
    pid: child.pid,
    signalSent,
    exitCode: child.exitCode,
    signalCode: child.signalCode,
    confirmedStopped: isStopped(),
    streamClosed
  };
}

async function waitForPath(filePath, processRecord, timeoutMs = 30_000) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    if (processRecord.child.exitCode !== null) {
      throw new Error(`Process exited before required path appeared: ${filePath}`);
    }
    try {
      await access(filePath);
      return;
    } catch {
      await sleep(200);
    }
  }
  throw new Error(`Timed out waiting for path: ${filePath}`);
}

function parseProcessTable(output) {
  return output.split(/\r?\n/).flatMap((line) => {
    const match = line.match(/^\s*(\d+)\s+(\d+)\s+(.*)$/);
    return match ? [{ pid: Number(match[1]), ppid: Number(match[2]), command: match[3] }] : [];
  });
}

export function descendantProcessIds(processRows, roots) {
  const selected = new Set(roots.filter((pid) => Number.isSafeInteger(pid) && pid > 0));
  let changed = true;
  while (changed) {
    changed = false;
    for (const row of processRows) {
      if (selected.has(row.ppid) && !selected.has(row.pid)) {
        selected.add(row.pid);
        changed = true;
      }
    }
  }
  return [...selected].sort((left, right) => left - right);
}

function parseRemoteHost(endpoint) {
  if (endpoint.startsWith('[')) {
    const close = endpoint.indexOf(']');
    return close > 0 ? endpoint.slice(1, close) : endpoint;
  }
  const colon = endpoint.lastIndexOf(':');
  return colon > 0 ? endpoint.slice(0, colon) : endpoint;
}

export function parseLsofOutbound(output) {
  return output.split(/\r?\n/).flatMap((line) => {
    const arrow = line.indexOf('->');
    if (arrow === -1) return [];
    const endpoint = line.slice(arrow + 2).trim().split(/\s+/)[0] ?? '';
    const host = parseRemoteHost(endpoint).toLowerCase();
    return [{
      endpoint,
      host,
      class: LOOPBACK_HOSTS.has(host) ? 'loopback' : 'external-non-allowlisted',
      line
    }];
  });
}

async function captureTcpSnapshot(rootPids) {
  const ps = await runCommand('ps', ['-axo', 'pid=,ppid=,command=']);
  if (ps.code !== 0) throw new Error(`ps failed: ${ps.stderr.trim()}`);
  const processRows = parseProcessTable(ps.stdout);
  const pids = descendantProcessIds(processRows, rootPids);
  if (pids.length === 0) return { at: nowIso(), pids, endpoints: [] };
  const lsof = await runCommand('lsof', [
    '-nP', '-a', '-p', pids.join(','), '-iTCP', '-sTCP:ESTABLISHED,SYN_SENT,CLOSE_WAIT'
  ]);
  const endpoints = lsof.code === 0 || lsof.code === 1 ? parseLsofOutbound(lsof.stdout) : [];
  if (lsof.code !== 0 && lsof.code !== 1) throw new Error(`lsof failed: ${lsof.stderr.trim()}`);
  return {
    at: nowIso(),
    pids,
    processes: processRows.filter((row) => pids.includes(row.pid)),
    endpoints
  };
}

function extractMarkedPayloads(logText, marker) {
  return logText.split(/\r?\n/).flatMap((line) => {
    const index = line.indexOf(marker);
    if (index === -1) return [];
    try {
      return [JSON.parse(line.slice(index + marker.length).trim())];
    } catch {
      return [{ parseError: true }];
    }
  });
}

function extractProbePayloads(logText) {
  return extractMarkedPayloads(logText, '[network-policy-probe]');
}

function probeResultFailed(probePayloads, url) {
  return probePayloads.some((payload) =>
    Array.isArray(payload.results) && payload.results.some((result) =>
      result.url === url && result.ok === false
    )
  );
}

export function summarizeNetworkEvidence(logText, snapshots) {
  const blockedDiagnostics = (logText.match(/Blocked renderer outbound request by network policy/g) ?? []).length;
  const egressDiagnostics = (logText.match(/anthropic_port_not_allowlisted:8443/g) ?? []).length;
  const probePayloads = extractProbePayloads(logText);
  const endpoints = snapshots.flatMap((snapshot) => snapshot.endpoints ?? []);
  const unique = [...new Map(endpoints.map((entry) => [entry.endpoint, entry])).values()];
  const nonAllowlisted = unique.filter((entry) => entry.class !== 'loopback');
  const blockedProbeObserved = probeResultFailed(probePayloads, BLOCKED_PROBE_URL);
  const loopbackProbeObserved = probeResultFailed(probePayloads, LOOPBACK_PROBE_URL);
  const egressPayloads = extractMarkedPayloads(logText, '[egress-layer-probe]');
  const expectedEgressDestination = (payload) =>
    payload?.destination?.protocol === EGRESS_PROBE_DESTINATION.protocol &&
    payload?.destination?.hostname === EGRESS_PROBE_DESTINATION.hostname &&
    payload?.destination?.port === EGRESS_PROBE_DESTINATION.port;
  const egressProbeObserved = egressPayloads.some(
    (payload) =>
      payload?.policy === 'REQ-NET-001' &&
      expectedEgressDestination(payload) &&
      payload?.outcome === 'rejected'
  );
  // The probe's destination is fixed in the app; a payload naming any other
  // destination (for example the decoy) means the app took a URL from outside.
  const egressProbeUnexpectedDestinations = egressPayloads
    .filter((payload) => !expectedEgressDestination(payload))
    .map((payload) => payload?.destination ?? null);
  return {
    snapshotCount: snapshots.length,
    sampledProcessIds: [...new Set(snapshots.flatMap((snapshot) => snapshot.pids ?? []))].sort(),
    uniqueOutboundTcp: unique.map(({ line: _line, ...entry }) => entry),
    nonAllowlistedOutboundTcp: nonAllowlisted.map(({ line: _line, ...entry }) => entry),
    blockedRendererDiagnostics: blockedDiagnostics,
    egressLayerDiagnostics: egressDiagnostics,
    probePayloadCount: probePayloads.length,
    egressProbePayloadCount: egressPayloads.length,
    blockedProbeObserved,
    loopbackProbeObserved,
    egressProbeObserved,
    egressProbeUnexpectedDestinations,
    pass:
      snapshots.length > 0 &&
      nonAllowlisted.length === 0 &&
      blockedDiagnostics > 0 &&
      egressDiagnostics > 0 &&
      blockedProbeObserved &&
      loopbackProbeObserved &&
      egressProbeObserved &&
      egressProbeUnexpectedDestinations.length === 0
  };
}

/**
 * Renderer hardening evidence (G-CSP): the document's CSP header as the page
 * itself sees it, a denied window.open, the CSP violation raised by a blocked
 * fetch, the main-process denial lines, and — as important — no violation
 * against the app's own resources.
 */
export function summarizeRendererSecurityEvidence(logText) {
  const payloads = extractMarkedPayloads(logText, '[renderer-security-probe]');
  const validPayloads = payloads.filter(
    (entry) => entry && entry.policy === 'G-CSP' && !entry.error && typeof entry.route === 'string'
  );
  const expectedViolation = (violation) =>
    typeof violation?.blockedURI === 'string' &&
    violation.blockedURI.startsWith('https://example.com') &&
    violation.effectiveDirective === 'connect-src' &&
    violation.disposition === 'enforce';
  const inspectPolicy = (cspHeader) => {
    const directives = typeof cspHeader === 'string'
      ? cspHeader.split(';').map((directive) => directive.trim())
      : [];
    const scriptDirective = directives.find((directive) => directive.startsWith('script-src ')) ?? '';
    const scriptSources = scriptDirective.split(/\s+/).slice(1);
    const nonceSources = scriptSources.filter((source) => /^'nonce-[A-Za-z0-9+/_-]+={0,2}'$/.test(source));
    const unsafeInlineAbsent = !scriptSources.includes("'unsafe-inline'");
    const unsafeEvalAbsent = !scriptSources.includes("'unsafe-eval'");
    return {
      header: typeof cspHeader === 'string' ? cspHeader : null,
      nonce: nonceSources.length === 1 ? nonceSources[0].slice(7, -1) : null,
      unsafeInlineAbsent,
      unsafeEvalAbsent,
      pass:
        directives.includes("default-src 'self'") &&
        directives.includes("connect-src 'self'") &&
        directives.includes("frame-src 'none'") &&
        directives.includes("object-src 'none'") &&
        scriptSources.includes("'self'") &&
        nonceSources.length === 1 &&
        unsafeInlineAbsent &&
        unsafeEvalAbsent
    };
  };
  const routeResults = PACKAGED_RENDERER_ROUTES.map((route) => {
    const matches = validPayloads.filter((entry) => entry.route === route);
    const payload = matches.length === 1 ? matches[0] : null;
    const responses = Array.isArray(payload?.consecutiveResponses)
      ? payload.consecutiveResponses
      : [];
    const responsePolicies = responses.map((response) => inspectPolicy(response?.cspHeader));
    const responseNonces = responsePolicies.map((policy) => policy.nonce);
    const violations = Array.isArray(payload?.violations) ? payload.violations : [];
    const expectedConnectViolation = violations.some(expectedViolation);
    const unexpected = violations.filter((violation) => !expectedViolation(violation));
    const consecutiveNoncesUnique =
      responseNonces.length === 2 &&
      responseNonces.every((nonce) => typeof nonce === 'string') &&
      responseNonces[0] !== responseNonces[1];
    const scriptUnsafeInlineAbsent =
      responsePolicies.length === 2 && responsePolicies.every((policy) => policy.unsafeInlineAbsent);
    const scriptUnsafeEvalAbsent =
      responsePolicies.length === 2 && responsePolicies.every((policy) => policy.unsafeEvalAbsent);
    const responsesConform =
      responses.length === 2 &&
      responses.every(
        (response, index) =>
          response?.status === 200 &&
          typeof response?.contentType === 'string' &&
          response.contentType.startsWith('text/html') &&
          response.documentComplete === true &&
          response.inlineScriptCount > 0 &&
          response.inlineScriptNoncesMatch === true &&
          responsePolicies[index]?.pass === true
      );
    return {
      route,
      payloadCount: matches.length,
      documentNonce: payload?.documentNonce ?? null,
      documentInlineScriptCount: payload?.documentInlineScriptCount ?? 0,
      documentInlineScriptNoncesMatch: payload?.documentInlineScriptNoncesMatch === true,
      responseNonces,
      consecutiveNoncesUnique,
      scriptUnsafeInlineAbsent,
      scriptUnsafeEvalAbsent,
      responsesConform,
      expectedConnectViolation,
      unexpectedViolations: unexpected,
      windowOpenReturnedNull: payload?.windowOpen?.returned === 'null',
      navigationAttempted: typeof payload?.navigationAttempted === 'string',
      pass:
        payload !== null &&
        typeof payload.documentNonce === 'string' &&
        payload.documentInlineScriptCount > 0 &&
        payload.documentInlineScriptNoncesMatch === true &&
        payload.responseError === null &&
        consecutiveNoncesUnique &&
        responsesConform &&
        expectedConnectViolation &&
        unexpected.length === 0 &&
        payload.windowOpen?.returned === 'null' &&
        typeof payload.navigationAttempted === 'string'
    };
  });
  const allObservedNonces = routeResults.flatMap((result) => [
    result.documentNonce,
    ...result.responseNonces
  ]).filter((nonce) => typeof nonce === 'string');
  const allObservedNoncesUnique =
    allObservedNonces.length === PACKAGED_RENDERER_ROUTES.length * 3 &&
    new Set(allObservedNonces).size === allObservedNonces.length;
  const unexpectedViolations = routeResults.flatMap((result) =>
    result.unexpectedViolations.map((violation) => ({ route: result.route, violation }))
  );
  const windowOpenDeniedCount = (logText.match(/renderer\.window_open\.denied/g) ?? []).length;
  const navigationDeniedCount = (logText.match(/renderer\.navigation\.denied/g) ?? []).length;
  const cspHeaderPresent = routeResults.every((result) => result.responsesConform);
  const cspViolationObserved = routeResults.every((result) => result.expectedConnectViolation);
  const windowOpenReturnedNull = routeResults.every((result) => result.windowOpenReturnedNull);
  const windowOpenDeniedLogged = windowOpenDeniedCount >= PACKAGED_RENDERER_ROUTES.length;
  const navigationDeniedLogged = navigationDeniedCount >= PACKAGED_RENDERER_ROUTES.length;
  return {
    probePayloadCount: payloads.length,
    requiredRoutes: PACKAGED_RENDERER_ROUTES,
    routeResults,
    allObservedNoncesUnique,
    cspHeaderPresent,
    cspViolationObserved,
    unexpectedViolations,
    windowOpenReturnedNull,
    windowOpenDeniedLogged,
    navigationAttempted: routeResults.every((result) => result.navigationAttempted),
    navigationDeniedLogged,
    pass:
      payloads.length === PACKAGED_RENDERER_ROUTES.length &&
      routeResults.every((result) => result.pass) &&
      allObservedNoncesUnique &&
      cspHeaderPresent &&
      cspViolationObserved &&
      unexpectedViolations.length === 0 &&
      windowOpenReturnedNull &&
      windowOpenDeniedLogged &&
      navigationDeniedLogged
  };
}

export function sensitiveMaterialFindings(text, values) {
  return values.flatMap(({ label, value }) => {
    const variants = [...new Set([value, encodeURIComponent(value)])];
    return variants.flatMap((variant) => text.includes(variant) ? [{ label, sha256: createHash('sha256').update(variant).digest('hex') }] : []);
  });
}

export function credentialProviderIsolation(statuses) {
  return (
    statuses.beforeOmlx.configured === false &&
    statuses.afterStoreOmlx.configured === false &&
    statuses.afterRemoveOmlx.configured === false
  );
}

export function evaluateCredentialEvidence(fixtureCredential, retainedSurfaces) {
  return Object.entries(retainedSurfaces).flatMap(([surface, text]) =>
    sensitiveMaterialFindings(String(text ?? ''), [
      { label: `fixture-credential:${surface}`, value: fixtureCredential }
    ])
  );
}

export function packagedProofPass({
  identityPresent,
  packagedPolicyPass,
  credentialProofPass,
  networkProofPass,
  rendererSecurityProofPass,
  cleanupPass,
  metadataLeakFindingCount
}) {
  return (
    identityPresent &&
    packagedPolicyPass &&
    credentialProofPass &&
    networkProofPass &&
    rendererSecurityProofPass === true &&
    cleanupPass &&
    metadataLeakFindingCount === 0
  );
}

async function runCredentialProof({ client, userDataRoot }) {
  const fixtureCredential = `packaged-proof-${randomUUID()}`;
  const credentialPath = path.join(userDataRoot, 'credentials', 'api-key.enc');
  const beforeAnthropic = await client.credentialStatus('anthropic');
  const beforeOmlx = await client.credentialStatus('omlx');
  const stored = await client.storeCredential('anthropic', fixtureCredential);
  const afterStore = await client.credentialStatus('anthropic');
  const afterStoreOmlx = await client.credentialStatus('omlx');
  const storedBytes = await readFile(credentialPath);
  const storedMetadata = await stat(credentialPath);
  const removed = await client.removeCredential('anthropic');
  const afterRemove = await client.credentialStatus('anthropic');
  const afterRemoveOmlx = await client.credentialStatus('omlx');
  let credentialFilePresentAfterRemove = true;
  try { await access(credentialPath); } catch { credentialFilePresentAfterRemove = false; }
  const rawStored = storedBytes.toString('utf8');
  const providerIsolation = credentialProviderIsolation({
    beforeOmlx,
    afterStoreOmlx,
    afterRemoveOmlx
  });
  const proof = {
    fixtureCredentialSha256: createHash('sha256').update(fixtureCredential).digest('hex'),
    before: { anthropic: beforeAnthropic, omlx: beforeOmlx },
    afterStore: { anthropic: afterStore, omlx: afterStoreOmlx },
    storedMutation: stored,
    encryptedBlob: {
      bytes: storedBytes.length,
      sha256: createHash('sha256').update(storedBytes).digest('hex'),
      ownerOnlyMode: (storedMetadata.mode & 0o777) === 0o600,
      excludesPlaintextFixture: !rawStored.includes(fixtureCredential)
    },
    removedMutation: removed,
    afterRemove: { anthropic: afterRemove, omlx: afterRemoveOmlx },
    credentialFilePresentAfterRemove,
    providerIsolation,
    mutationPass:
      beforeAnthropic.configured === false &&
      beforeOmlx.configured === false &&
      stored.configured === true &&
      afterStore.configured === true &&
      afterStoreOmlx.configured === false &&
      storedBytes.length > 0 &&
      (storedMetadata.mode & 0o777) === 0o600 &&
      !rawStored.includes(fixtureCredential) &&
      removed.configured === false &&
      afterRemove.configured === false &&
      afterRemoveOmlx.configured === false &&
      !credentialFilePresentAfterRemove &&
      providerIsolation
  };
  return { fixtureCredential, rawStored, proof };
}

async function currentGitRevision() {
  const result = await runCommand('git', ['rev-parse', 'HEAD'], { cwd: FRONTEND_ROOT });
  if (result.code !== 0) throw new Error(`git rev-parse failed: ${result.stderr.trim()}`);
  return result.stdout.trim();
}

async function writeJson(filePath, value) {
  await writeFile(filePath, `${JSON.stringify(value, null, 2)}\n`, 'utf8');
}

async function readEmittedArtifacts(rootPath, relativePath = '') {
  const directoryPath = path.join(rootPath, relativePath);
  const entries = await readdir(directoryPath, { withFileTypes: true });
  const artifacts = {};
  for (const entry of entries) {
    const childRelativePath = path.join(relativePath, entry.name);
    if (entry.isDirectory()) {
      Object.assign(artifacts, await readEmittedArtifacts(rootPath, childRelativePath));
    } else if (entry.isFile()) {
      artifacts[childRelativePath] = (await readFile(path.join(rootPath, childRelativePath))).toString('utf8');
    }
  }
  return artifacts;
}

export async function runProof(args) {
  const startedAt = nowIso();
  const sourceRevision = await currentGitRevision();
  if (args.sourceRevision && args.sourceRevision !== sourceRevision) {
    throw new Error(`Source revision mismatch: expected ${args.sourceRevision}, current ${sourceRevision}`);
  }
  await mkdir(args.outputRoot, { recursive: true });
  // AF_UNIX paths are short on macOS. `/tmp` is the system's canonical short
  // alias for the longer per-user temp path returned by os.tmpdir().
  const tempRoot = await mkdtemp(path.join('/tmp', 'chirality-psp-'));
  const userDataRoot = path.join(tempRoot, 'user-data');
  const extractionRoot = path.join(tempRoot, 'asar-extract');
  await mkdir(userDataRoot, { recursive: true, mode: 0o700 });
  await chmod(userDataRoot, 0o700);
  await mkdir(extractionRoot, { recursive: true });

  const identity = await captureAppIdentity(args.appPath, sourceRevision);
  const packagedMain = await extractPackagedMain(args.appPath, extractionRoot);
  const packagedPolicy = inspectPackagedPolicyMarkers(packagedMain);
  const executablePath = path.join(identity.appPath, 'Contents', 'MacOS', 'Chirality');
  const daemonLogPath = path.join(args.outputRoot, 'packaged-daemon.log');
  const guiLogPath = path.join(args.outputRoot, 'packaged-gui.log');
  const socketPath = path.join(userDataRoot, 'runtime', 'control.sock');
  const tokenFile = path.join(userDataRoot, 'runtime', 'auth', 'tokens', 'operator.token');
  const cleanEnv = { ...process.env };
  delete cleanEnv.ANTHROPIC_API_KEY;
  delete cleanEnv.CHIRALITY_ANTHROPIC_API_KEY;
  delete cleanEnv.CHIRALITY_OMLX_API_KEY;
  const proofEnv = {
    ...cleanEnv,
    CHIRALITY_USER_DATA: userDataRoot,
    CHIRALITY_SKIP_CLI_LAUNCHER: '1',
    CHIRALITY_NETWORK_POLICY_PROBE_URLS: [BLOCKED_PROBE_URL, LOOPBACK_PROBE_URL].join(','),
    CHIRALITY_NETWORK_POLICY_PROBE_DELAY_MS: '1000',
    CHIRALITY_NETWORK_POLICY_PROBE_TIMEOUT_MS: '3000',
    CHIRALITY_RENDERER_SECURITY_PROBE: '1',
    CHIRALITY_RENDERER_SECURITY_PROBE_DELAY_MS: '1500',
    CHIRALITY_EGRESS_LAYER_PROBE_URL: EGRESS_PROBE_DECOY_URL
  };

  let daemon;
  let gui;
  let credentialInternal;
  let snapshots = [];
  let operationError;
  try {
    daemon = startLoggedProcess({
      label: 'packaged-runtime-daemon',
      command: executablePath,
      args: ['--runtime-daemon'],
      env: proofEnv,
      logPath: daemonLogPath
    });
    await waitForPath(socketPath, daemon);
    await waitForPath(tokenFile, daemon);
    const client = new RuntimeClient({ socketPath, tokenFile });
    await client.daemonStatus();

    credentialInternal = await runCredentialProof({
      client,
      userDataRoot
    });

    gui = startLoggedProcess({
      label: 'packaged-gui',
      command: executablePath,
      args: [],
      env: proofEnv,
      logPath: guiLogPath
    });
    const deadline = Date.now() + args.captureSeconds * 1000;
    while (Date.now() < deadline && gui.child.exitCode === null && gui.child.signalCode === null) {
      snapshots.push(await captureTcpSnapshot([daemon.child.pid, gui.child.pid]));
      const combined = `${gui.captured()}\n${daemon.captured()}`;
      const rendererProbeCount = (combined.match(/\[renderer-security-probe\]/g) ?? []).length;
      const navigationDenialCount = (combined.match(/renderer\.navigation\.denied/g) ?? []).length;
      if (
        combined.includes('Blocked renderer outbound request by network policy') &&
        combined.includes('[network-policy-probe]') &&
        rendererProbeCount >= PACKAGED_RENDERER_ROUTES.length &&
        combined.includes('[egress-layer-probe]') &&
        navigationDenialCount >= PACKAGED_RENDERER_ROUTES.length &&
        snapshots.length >= 4
      ) break;
      await sleep(300);
    }
    await writeJson(path.join(args.outputRoot, 'tcp-snapshots.json'), snapshots);
  } catch (error) {
    operationError = error;
  }

  const guiShutdown = await stopProcess(gui, 'packaged GUI').catch((error) => ({
    label: 'packaged GUI',
    started: Boolean(gui),
    confirmedStopped: false,
    streamClosed: false,
    error: error instanceof Error ? error.message : String(error)
  }));
  const daemonShutdown = await stopProcess(daemon, 'packaged runtime daemon').catch((error) => ({
    label: 'packaged runtime daemon',
    started: Boolean(daemon),
    confirmedStopped: false,
    streamClosed: false,
    error: error instanceof Error ? error.message : String(error)
  }));
  let tempRootRemoved = false;
  let tempRootRemovalError = null;
  try {
    await rm(tempRoot, { recursive: true, force: true });
    tempRootRemoved = true;
  } catch (error) {
    tempRootRemovalError = error instanceof Error ? error.message : String(error);
  }
  const cleanup = {
    gui: guiShutdown,
    daemon: daemonShutdown,
    tempRootRemoved,
    tempRootRemovalError,
    pass:
      guiShutdown.started === true &&
      guiShutdown.confirmedStopped === true &&
      guiShutdown.streamClosed === true &&
      daemonShutdown.started === true &&
      daemonShutdown.confirmedStopped === true &&
      daemonShutdown.streamClosed === true &&
      tempRootRemoved
  };
  await writeJson(path.join(args.outputRoot, 'cleanup.json'), cleanup);

  if (operationError) {
    throw new Error(
      `${operationError instanceof Error ? operationError.message : String(operationError)}; cleanup=${cleanup.pass ? 'confirmed' : 'FAILED'}`
    );
  }

  const daemonLog = await readFile(daemonLogPath, 'utf8');
  const guiLog = await readFile(guiLogPath, 'utf8');
  const combinedClosedLogs = `${daemonLog}\n${guiLog}`;
  const emittedArtifacts = await readEmittedArtifacts(args.outputRoot);
  const retainedSurfaces = {
    encryptedCredentialArtifact: credentialInternal.rawStored,
    ...Object.fromEntries(
      Object.entries(emittedArtifacts).map(([artifactPath, text]) => [`emitted:${artifactPath}`, text])
    )
  };
  const retainedSecretFindings = evaluateCredentialEvidence(
    credentialInternal.fixtureCredential,
    retainedSurfaces
  );
  const credentialProof = {
    ...credentialInternal.proof,
    retainedSecretFindings,
    evidenceSurfacesScannedAfterStreamClosure: Object.keys(retainedSurfaces),
    pass: credentialInternal.proof.mutationPass && retainedSecretFindings.length === 0
  };
  const networkProof = summarizeNetworkEvidence(combinedClosedLogs, snapshots);
  const rendererSecurityProof = summarizeRendererSecurityEvidence(combinedClosedLogs);
  const genericSensitiveFindings = [
    /https?:\/\/[^\s/@:]+:[^\s/@]+@/u,
    /[?&](?:api[_-]?key|token|credential|password)=/iu
  ].flatMap((pattern) => pattern.test(combinedClosedLogs) ? [{ pattern: pattern.source }] : []);
  const summary = {
    schema: 'chirality-packaged-security-proof/v1',
    status: packagedProofPass({
      identityPresent: Boolean(identity),
      packagedPolicyPass: packagedPolicy.allPresent,
      credentialProofPass: credentialProof.pass,
      networkProofPass: networkProof.pass,
      rendererSecurityProofPass: rendererSecurityProof.pass,
      cleanupPass: cleanup.pass,
      metadataLeakFindingCount: genericSensitiveFindings.length
    }) ? 'pass' : 'fail',
    startedAt,
    completedAt: nowIso(),
    proofBoundary: 'fresh-unsigned-packaged-app-network-safeStorage-renderer-hardening-and-security-byte-presence',
    artifactIdentity: identity,
    packagedPolicy,
    credentialProof,
    networkProof,
    rendererSecurityProof,
    cleanup,
    retainedMetadataLeakFindings: genericSensitiveFindings,
    exclusions: {
      realCredentialsUsed: false,
      signingOrNotarization: false,
      distributionOrPublication: false,
      ownerUserDataTouched: false,
      providerScopeExpanded: false
    }
  };
  await writeJson(path.join(args.outputRoot, 'summary.json'), summary);
  if (summary.status !== 'pass') process.exitCode = 1;
  return summary;
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (args.help) {
    process.stdout.write(usage());
    return;
  }
  const summary = await runProof(args);
  process.stdout.write(`packaged security proof status: ${summary.status}\n`);
  process.stdout.write(`summary: ${path.join(args.outputRoot, 'summary.json')}\n`);
}

if (process.argv[1] && path.resolve(process.argv[1]) === SCRIPT_PATH) {
  main().catch((error) => {
    console.error(error instanceof Error ? error.message : String(error));
    process.exitCode = 1;
  });
}

