} from '../../../scripts/run-packaged-security-proof.mjs';

describe('run-packaged-security-proof script', () => {
  it('normalizes explicit packaged proof inputs', () => {
    const args = parseArgs([
      '--app-path',
      './dist/mac-arm64/Chirality.app',
      '--output-root',
      './artifacts/proof',
      '--source-revision',
      'abc123',
      '--capture-seconds',
      '9'
    ]);

    expect(args.appPath).toContain('/dist/mac-arm64/Chirality.app');
    expect(args.outputRoot).toContain('/artifacts/proof');
    expect(args.sourceRevision).toBe('abc123');
    expect(args.captureSeconds).toBe(9);
  });

  it('captures the complete packaged descendant process tree', () => {
    expect(
      descendantProcessIds(
        [
          { pid: 10, ppid: 1, command: 'packaged-gui' },
          { pid: 11, ppid: 10, command: 'renderer' },
          { pid: 12, ppid: 11, command: 'network-service' },
          { pid: 99, ppid: 1, command: 'unrelated' }
        ],
        [10]
      )
    ).toEqual([10, 11, 12]);
  });

  it('fails closed on non-loopback TCP while accepting isolated loopback traffic', () => {
    const parsed = parseLsofOutbound([
      'Chirality 10 user 20u IPv4 TCP 127.0.0.1:5000->127.0.0.1:6000 (ESTABLISHED)',
      'Chirality 11 user 21u IPv4 TCP 127.0.0.1:5001->203.0.113.4:443 (SYN_SENT)'
    ].join('\n'));

    expect(parsed.map((entry: { class: string }) => entry.class)).toEqual([
      'loopback',
      'external-non-allowlisted'
    ]);
  });

  it('expects exactly the egress-probe destination the app fixes, and sets only a loopback decoy in the environment', () => {
    // DEL-09-06-V3-05: the app never reads the probe URL from the environment;
    // the proof's expectation must be byte-equal to the app's constant.
    expect(EGRESS_PROBE_URL).toBe(EGRESS_LAYER_PROBE_URL);
    const destination = new URL(EGRESS_PROBE_URL);
    expect(destination.hostname).toBe('api.anthropic.com');
    expect(destination.port).toBe('8443');
    // The decoy is a destination the egress policy would allow (loopback) but that
    // refuses the connection on the host itself: nothing can leave the machine
    // even if a regression made the app honour the variable again.
    const decoy = new URL(EGRESS_PROBE_DECOY_URL);
    expect(decoy.hostname).toBe('127.0.0.1');
    expect(decoy.port).toBe('9');
    expect(EGRESS_PROBE_DECOY_URL).not.toBe(EGRESS_PROBE_URL);
  });

  it('requires blocked diagnostics, all three probes, and zero non-allowlisted TCP', () => {
    const egressPayload = '{"policy":"REQ-NET-001","destination":{"protocol":"https:","hostname":"api.anthropic.com","port":"8443"},"outcome":"rejected","error":"net::ERR_BLOCKED_BY_CLIENT"}';
    const logText = [
      'Blocked renderer outbound request by network policy { destination: redacted }\n',
      "Blocked renderer outbound request by network policy { reason: 'anthropic_port_not_allowlisted:8443' }\n",
      '[network-policy-probe] {"policy":"REQ-NET-001","results":[',
      '{"url":"https://example.com/chirality-packaged-security-blocked","ok":false},',
      '{"url":"http://127.0.0.1:9/chirality-packaged-security-loopback","ok":false}]}\n',
      `[egress-layer-probe] ${egressPayload}`
    ].join('');
    const snapshots = [
      { pids: [10, 11], endpoints: [{ endpoint: '127.0.0.1:6000', host: '127.0.0.1', class: 'loopback', line: 'fixture' }] }
    ];
    const summary = summarizeNetworkEvidence(logText, snapshots);

    expect(summary.pass).toBe(true);
    expect(summary.egressLayerDiagnostics).toBe(1);
    expect(summary.egressProbeObserved).toBe(true);
    expect(summary.egressProbeUnexpectedDestinations).toEqual([]);
    expect(summary.nonAllowlistedOutboundTcp).toEqual([]);

    // The egress layer must be observed on its own, from the main-process
    // probe: a CSP-only block of the example.com probe is not enough, and a
    // probe that got a response means the egress layer let it through.
    const cspOnly = logText.replace(
      "Blocked renderer outbound request by network policy { reason: 'anthropic_port_not_allowlisted:8443' }\n",
      ''
    );
    expect(summarizeNetworkEvidence(cspOnly, snapshots).pass).toBe(false);
    const responded = logText.replace('"outcome":"rejected"', '"outcome":"response","status":200');
    expect(summarizeNetworkEvidence(responded, snapshots).egressProbeObserved).toBe(false);
    expect(summarizeNetworkEvidence(responded, snapshots).pass).toBe(false);

    // The probe destination is fixed in the app (DEL-09-06-V3-05): a payload for the
    // allowlisted port, for a destination without the port, or for any other
    // destination (the loopback decoy the proof sets in the environment) is not
    // the expected observation and fails the proof.
    const allowlistedPort = logText.replace('"port":"8443"', '"port":"443"');
    expect(summarizeNetworkEvidence(allowlistedPort, snapshots).egressProbeObserved).toBe(false);
    expect(summarizeNetworkEvidence(allowlistedPort, snapshots).egressProbeUnexpectedDestinations).toEqual([
      { protocol: 'https:', hostname: 'api.anthropic.com', port: '443' }
    ]);
    expect(summarizeNetworkEvidence(allowlistedPort, snapshots).pass).toBe(false);
    const portless = logText.replace(',"port":"8443"', '');
    expect(summarizeNetworkEvidence(portless, snapshots).egressProbeObserved).toBe(false);
    expect(summarizeNetworkEvidence(portless, snapshots).pass).toBe(false);
    const decoyFollowed = logText.replace(
      '{"protocol":"https:","hostname":"api.anthropic.com","port":"8443"}',
      '{"protocol":"http:","hostname":"127.0.0.1","port":"9"}'
    );
    const decoySummary = summarizeNetworkEvidence(decoyFollowed, snapshots);
    expect(decoySummary.egressProbeObserved).toBe(false);
    expect(decoySummary.egressProbeUnexpectedDestinations).toEqual([
      { protocol: 'http:', hostname: '127.0.0.1', port: '9' }
    ]);
    expect(decoySummary.pass).toBe(false);
    // An extra payload for another destination fails even beside the expected one.
    const extraDestination = `${logText}\n[egress-layer-probe] {"policy":"REQ-NET-001","destination":{"protocol":"http:","hostname":"127.0.0.1","port":"9"},"outcome":"rejected","error":"net::ERR_CONNECTION_REFUSED"}`;
    const extraSummary = summarizeNetworkEvidence(extraDestination, snapshots);
    expect(extraSummary.egressProbeObserved).toBe(true);
    expect(extraSummary.egressProbeUnexpectedDestinations).toHaveLength(1);
    expect(extraSummary.pass).toBe(false);
  });

  it('fails closed when the egress-layer probe line is absent', () => {
    const logText = [
      'Blocked renderer outbound request by network policy { destination: redacted }',
      "Blocked renderer outbound request by network policy { reason: 'anthropic_port_not_allowlisted:8443' }",
      '[network-policy-probe] {"policy":"REQ-NET-001","results":[{"url":"https://example.com/chirality-packaged-security-blocked","ok":false},{"url":"http://127.0.0.1:9/chirality-packaged-security-loopback","ok":false}]}'
    ].join('\n');
    const snapshots = [
      { pids: [10], endpoints: [{ endpoint: '127.0.0.1:6000', host: '127.0.0.1', class: 'loopback', line: 'fixture' }] }
    ];

    const summary = summarizeNetworkEvidence(logText, snapshots);

    expect(summary.blockedProbeObserved).toBe(true);
    expect(summary.loopbackProbeObserved).toBe(true);
    expect(summary.egressProbePayloadCount).toBe(0);
    expect(summary.egressProbeObserved).toBe(false);
    expect(summary.pass).toBe(false);
  });

  it('fails closed when the egress-layer probe payload is malformed', () => {
    const logText = [
      'Blocked renderer outbound request by network policy { destination: redacted }',
      "Blocked renderer outbound request by network policy { reason: 'anthropic_port_not_allowlisted:8443' }",
      '[network-policy-probe] {"policy":"REQ-NET-001","results":[{"url":"https://example.com/chirality-packaged-security-blocked","ok":false},{"url":"http://127.0.0.1:9/chirality-packaged-security-loopback","ok":false}]}',
      '[egress-layer-probe] not-json'
    ].join('\n');
    const snapshots = [
      { pids: [10], endpoints: [{ endpoint: '127.0.0.1:6000', host: '127.0.0.1', class: 'loopback', line: 'fixture' }] }
    ];

    const summary = summarizeNetworkEvidence(logText, snapshots);

    expect(summary.blockedProbeObserved).toBe(true);
    expect(summary.loopbackProbeObserved).toBe(true);
    expect(summary.egressProbePayloadCount).toBe(1);
    expect(summary.egressProbeObserved).toBe(false);
    expect(summary.egressProbeUnexpectedDestinations).toEqual([null]);
    expect(summary.pass).toBe(false);
  });

  it('requires the renderer hardening evidence from the packaged page', () => {
    const policy = (nonce: string) =>
      `default-src 'self'; script-src 'self' 'nonce-${nonce}'; connect-src 'self'; frame-src 'none'; object-src 'none'`;
    const payloadFor = (route: string, index: number) => {
      const documentNonce = `documentNonce${index}`;
      const firstNonce = `responseNonce${index}a`;
      const secondNonce = `responseNonce${index}b`;
      return {
        policy: 'G-CSP',
        route,
        documentNonce,
        documentInlineScriptCount: 5,
        documentInlineScriptNoncesMatch: true,
        consecutiveResponses: [firstNonce, secondNonce].map((responseNonce) => ({
          status: 200,
          contentType: 'text/html; charset=utf-8',
          cspHeader: policy(responseNonce),
          responseNonce,
          inlineScriptCount: 5,
          inlineScriptNoncesMatch: true,
          documentComplete: true
        })),
        responseError: null,
        windowOpen: { returned: 'null' },
        violations: [
          { blockedURI: 'https://example.com', effectiveDirective: 'connect-src', disposition: 'enforce' }
        ],
        navigationAttempted: 'https://example.com/chirality-renderer-security-navigation'
      };
    };
    const payloads = PACKAGED_RENDERER_ROUTES.map(payloadFor);
    const logText = [
      ...payloads.map((payload) => `[renderer-security-probe] ${JSON.stringify(payload)}`),
      ...PACKAGED_RENDERER_ROUTES.map(
        () => '[chirality-desktop] [warn] renderer.window_open.denied {"destination":{"protocol":"about:","hostname":""}}'
      ),
      ...PACKAGED_RENDERER_ROUTES.map(
        () => '[chirality-desktop] [warn] renderer.navigation.denied {"event":"will-navigate","reason":"ORIGIN_NOT_RENDERER"}'
      )
    ].join('\n');

    const summary = summarizeRendererSecurityEvidence(logText);
    expect(summary).toMatchObject({
      probePayloadCount: 4,
      allObservedNoncesUnique: true,
      cspHeaderPresent: true,
      cspViolationObserved: true,
      unexpectedViolations: [],
      windowOpenReturnedNull: true,
      windowOpenDeniedLogged: true,
      navigationAttempted: true,
      navigationDeniedLogged: true,
      pass: true
    });
    expect(summary.routeResults.map((result: { route: string; pass: boolean }) => [result.route, result.pass])).toEqual(
      PACKAGED_RENDERER_ROUTES.map((route) => [route, true])
    );
    expect(
      summary.routeResults.every(
        (result: { scriptUnsafeInlineAbsent: boolean; scriptUnsafeEvalAbsent: boolean }) =>
          result.scriptUnsafeInlineAbsent && result.scriptUnsafeEvalAbsent
      )
    ).toBe(true);

    expect(summarizeRendererSecurityEvidence(logText.replace('renderer.navigation.denied', 'x')).pass).toBe(false);
    expect(summarizeRendererSecurityEvidence(logText.replace('"returned":"null"', '"returned":"object"')).pass).toBe(false);
    const unsafeInline = summarizeRendererSecurityEvidence(
      logText.replace("script-src 'self' 'nonce-responseNonce0a'", "script-src 'self' 'unsafe-inline'")
    );
    expect(unsafeInline.routeResults[0].scriptUnsafeInlineAbsent).toBe(false);
    expect(unsafeInline.pass).toBe(false);
    // Exact directives only: the superseded port-wildcard form must not pass.
    const wildcard = summarizeRendererSecurityEvidence(
      logText.replace("connect-src 'self';", "connect-src 'self' https://api.anthropic.com:*;")
    );
    expect(wildcard.cspHeaderPresent).toBe(false);
    expect(wildcard.pass).toBe(false);
    expect(summarizeRendererSecurityEvidence(logText.replace("connect-src 'self';", "connect-src 'self' https://example.com;")).cspHeaderPresent).toBe(false);
    expect(summarizeRendererSecurityEvidence(logText.replace("frame-src 'none';", "frame-src 'self';")).cspHeaderPresent).toBe(false);
    const ownResourceViolation = JSON.stringify({
      ...payloads[0],
      violations: [
        ...payloads[0].violations,
        {
          blockedURI: 'http://127.0.0.1:41234/_next/static/x.js',
          effectiveDirective: 'script-src-elem'
        }
      ]
    });
    const withOwnViolation = summarizeRendererSecurityEvidence(
      logText.replace(JSON.stringify(payloads[0]), ownResourceViolation)
    );
    expect(withOwnViolation.unexpectedViolations).toHaveLength(1);
    expect(withOwnViolation.pass).toBe(false);
    expect(
      summarizeRendererSecurityEvidence(
        logText.replace('responseNonce1a', 'responseNonce0a')
      ).allObservedNoncesUnique
    ).toBe(false);
    expect(
      summarizeRendererSecurityEvidence(
        logText.replace(`[renderer-security-probe] ${JSON.stringify(payloads[3])}`, '')
      ).pass
    ).toBe(false);
    expect(summarizeRendererSecurityEvidence('no probe at all').pass).toBe(false);
  });

  it('requires every packaged security marker and reports only hashes for fixture leaks', () => {
    const packagedMain = [
      'REQ-NET-001',
      'api.anthropic.com',
      'anthropic_protocol_not_allowlisted',
      'anthropic_port_not_allowlisted',
      'host_not_allowlisted',
      'Blocked renderer outbound request by network policy',
      'Attachment exceeds per-file size limit',
      'Attachment exceeds per-turn size budget',
      'symbolic links are rejected',
      'ATTACHMENT_FAILURE',
      'Content-Security-Policy',
      'renderer.window_open.denied',
      'renderer.navigation.denied'
    ].join('\n');
    expect(inspectPackagedPolicyMarkers(packagedMain).allPresent).toBe(true);
    expect(inspectPackagedPolicyMarkers(packagedMain.replace('renderer.navigation.denied', '')).allPresent).toBe(false);

    const findings = sensitiveMaterialFindings('log has proof-key-value', [
      { label: 'fixture', value: 'proof-key-value' }
    ]);
    expect(findings).toHaveLength(1);
    expect(findings[0]).toEqual({
      label: 'fixture',
      sha256: expect.stringMatching(/^[a-f0-9]{64}$/)
    });
    expect(JSON.stringify(findings)).not.toContain('proof-key-value');
  });

  it('fails credential evidence when an operation-time stream leaks the fixture', () => {
    const fixture = 'packaged-proof-fixture-not-a-secret';
    const findings = evaluateCredentialEvidence(fixture, {
      beforeOperations: 'clean',
      completeDaemonStream: `credential stored: ${fixture}`,
      completeGuiStream: 'clean after stream closure'
    });

    expect(findings).toHaveLength(1);
    expect(findings[0].label).toBe('fixture-credential:completeDaemonStream');
    expect(JSON.stringify(findings)).not.toContain(fixture);
  });

  it('fails provider isolation when Anthropic mutation changes oMLX', () => {
    expect(
      credentialProviderIsolation({
        beforeOmlx: { configured: false },
        afterStoreOmlx: { configured: true },
        afterRemoveOmlx: { configured: false }
      })
    ).toBe(false);
  });

  it('requires confirmed cleanup in the final PASS predicate', () => {
    const otherwisePassing = {
      identityPresent: true,
      packagedPolicyPass: true,
      credentialProofPass: true,
      networkProofPass: true,
      rendererSecurityProofPass: true,
      metadataLeakFindingCount: 0
    };

    expect(packagedProofPass({ ...otherwisePassing, cleanupPass: true })).toBe(true);
    expect(packagedProofPass({ ...otherwisePassing, cleanupPass: false })).toBe(false);
  });
});

import { constants } from 'node:fs';
import { access, open, realpath, stat } from 'node:fs/promises';
import path from 'node:path';

export const TEXT_LIMIT = 10 * 1024 * 1024;
export class FilePolicyError extends Error {
  constructor(public code: string, public status: number, message: string) { super(message); }
}
function within(root: string, target: string): boolean {
  const relative = path.relative(root, target);
  return relative === '' || (!relative.startsWith(`..${path.sep}`) && relative !== '..' && !path.isAbsolute(relative));
}
function forbidden(root: string, target: string, instruction: string): void {
  if (!within(root, target) || within(instruction, target) ||
      path.relative(root, target).split(path.sep).includes('.git')) {
    throw new FilePolicyError('FILE_FORBIDDEN', 403, 'File is outside the allowed Working Root.');
  }
}
export async function validateDocumentTarget(input: unknown, instructionRoot: string) {
  if (!input || typeof input !== 'object' || Array.isArray(input)) throw new FilePolicyError('INVALID_REQUEST', 400, 'Expected a root and relative file path.');
  const { projectRoot, target } = input as Record<string, unknown>;
  if (typeof projectRoot !== 'string' || !path.isAbsolute(projectRoot) || /[\x00-\x1f]/.test(projectRoot) ||
      typeof target !== 'string' || !target || path.isAbsolute(target) || /[\x00-\x1f\\]/.test(target) ||
      target.split('/').some(segment => segment === '..' || segment === '.' || segment === '')) {
    throw new FilePolicyError('INVALID_REQUEST', 400, 'Expected an absolute root and a relative file path without traversal.');
  }
  const root = path.resolve(projectRoot), lexical = path.resolve(root, target);
  const instruction = path.resolve(instructionRoot);
  if (within(instruction, root)) throw new FilePolicyError('WORKING_ROOT_CONFLICT', 409, 'Working Root cannot be inside the instruction root.');
  forbidden(root, lexical, instruction);
  const [canonicalRoot, canonicalInstruction, canonical] = await Promise.all([realpath(root), realpath(instruction), realpath(lexical)]);
  if (within(canonicalInstruction, canonicalRoot)) throw new FilePolicyError('WORKING_ROOT_CONFLICT', 409, 'Working Root cannot be inside the instruction root.');
  forbidden(canonicalRoot, canonical, canonicalInstruction);
  if (!(await stat(canonicalRoot)).isDirectory()) throw new FilePolicyError('WORKING_ROOT_INACCESSIBLE', 404, 'Working Root must be a directory.');
  await access(canonicalRoot, constants.R_OK | constants.W_OK);
  const info = await stat(canonical);
  if (!info.isFile()) throw new FilePolicyError('NOT_REGULAR_FILE', 400, 'Only regular files can be viewed.');
  return { canonical, canonicalRoot, target, info };
}
/** Open a validated descriptor; reads stay bound to this inode, even after rename. */
export async function openDocument(input: unknown, instructionRoot: string) {
  const before = await validateDocumentTarget(input, instructionRoot);
  const handle = await open(before.canonical, constants.O_RDONLY | constants.O_NOFOLLOW | constants.O_NONBLOCK);
  try {
    const info = await handle.stat();
    const after = await validateDocumentTarget(input, instructionRoot);
    if (!info.isFile() || info.dev !== before.info.dev || info.ino !== before.info.ino ||
        info.dev !== after.info.dev || info.ino !== after.info.ino || before.canonical !== after.canonical) {
      throw new FilePolicyError('FILE_CHANGED', 409, 'File changed while opening. Retry the preview.');
    }
    return { ...after, info, handle };
  } catch (error) { await handle.close(); throw error; }
}
export function fileError(error: unknown): { status: number; body: { error: { code: string; message: string } } } {
  if (error instanceof FilePolicyError) return { status: error.status, body: { error: { code: error.code, message: error.message } } };
  const code = (error as NodeJS.ErrnoException)?.code;
  if (code === 'ENOENT' || code === 'ENOTDIR') return { status: 404, body: { error: { code: 'FILE_NOT_FOUND', message: 'File or Working Root no longer exists.' } } };
  if (code === 'EACCES' || code === 'EPERM') return { status: 403, body: { error: { code: 'FILE_INACCESSIBLE', message: 'File cannot be accessed.' } } };
  if (code === 'ELOOP') return { status: 409, body: { error: { code: 'FILE_CHANGED', message: 'File link changed or is circular.' } } };
  return { status: 500, body: { error: { code: 'FILE_READ_FAILED', message: 'Unable to read the file.' } } };
}
export type DocumentHandoffDependencies<E> = {
  authorized: (event: E) => boolean;
  instructionRoot: () => string;
  preview: (event: E, target: string) => void;
  open: (target: string) => Promise<string>;
};
/** Shared boundary used by the actual main-process registration; no shell command bridge. */
export function createDocumentHandoffHandler<E>(deps: DocumentHandoffDependencies<E>) {
  return async (event: E, input: unknown) => {
    if (!deps.authorized(event)) return { ok: false, error: { code: 'UNAUTHORIZED_SENDER', message: 'Document action rejected for this sender.' } };
    try {
      const action = (input as { action?: unknown } | null)?.action;
      if (action !== 'quick-look' && action !== 'open') throw new FilePolicyError('INVALID_REQUEST', 400, 'Unknown document action.');
      const document = await openDocument(input, deps.instructionRoot());
      try {
        // Native APIs take a path, so validate again immediately before handing it off.
        const current = await validateDocumentTarget(input, deps.instructionRoot());
        if (current.info.ino !== document.info.ino || current.info.dev !== document.info.dev) throw new FilePolicyError('FILE_CHANGED', 409, 'File changed before opening. Retry.');
        if (action === 'quick-look') {
          try { deps.preview(event, current.canonical); }
          catch (error) { throw error instanceof FilePolicyError ? error : new FilePolicyError('PREVIEW_FAILED', 502, error instanceof Error ? error.message : 'Quick Look could not open this file.'); }
        }
        else {
          try {
            const error = await deps.open(current.canonical);
            if (error) throw new FilePolicyError('OPEN_FAILED', 502, error);
          } catch (error) { throw error instanceof FilePolicyError ? error : new FilePolicyError('OPEN_FAILED', 502, error instanceof Error ? error.message : 'Default app could not open this file.'); }
        }
      } finally { await document.handle.close(); }
      return { ok: true };
    } catch (error) { return { ok: false, ...fileError(error).body }; }
  };
}

import path from 'node:path';
import { NextResponse } from 'next/server';
import { assertProjectRootAccessible } from '../../../../lib/harness/session-manager';
import { resolveInstructionRootPath } from '../../../../lib/harness/instruction-root';
import { fileError, openDocument, TEXT_LIMIT, FilePolicyError } from './file-policy';

export const runtime = 'nodejs';
const TEXT = new Set(['.md', '.markdown', '.txt', '.log', '.csv', '.json', '.yaml', '.yml', '.toml', '.js', '.jsx', '.ts', '.tsx', '.py', '.css', '.html', '.xml', '.sh', '.sql', '.rs', '.go', '.c', '.h', '.cpp', '.java', '.ini', '.cfg']);
const OFFICE = new Set(['.docx', '.xlsx', '.pptx']);
export async function GET(request: Request): Promise<Response> {
  let document: Awaited<ReturnType<typeof openDocument>> | undefined;
  try {
    const url = new URL(request.url);
    const projectRoot = await assertProjectRootAccessible(url.searchParams.get('projectRoot') ?? '');
    const targetPath = url.searchParams.get('path') ?? url.searchParams.get('target');
    if (url.searchParams.has('path') && url.searchParams.has('target') && url.searchParams.get('target') !== targetPath) throw new FilePolicyError('INVALID_REQUEST', 400, 'Conflicting file paths.');
    document = await openDocument({ projectRoot, target: targetPath }, resolveInstructionRootPath());
    const { handle, info, target } = document;
    const extension = path.extname(target).toLowerCase();
    const kind = extension === '.pdf' ? 'pdf' : OFFICE.has(extension) ? 'office' : TEXT.has(extension) || !extension ? 'text' : 'unsupported';
    const mimeType = kind === 'pdf' ? 'application/pdf' : extension === '.csv' ? 'text/csv' : extension === '.md' || extension === '.markdown' ? 'text/markdown' : kind === 'text' ? 'text/plain' : 'application/octet-stream';
    const metadata = { path: target, mtime: info.mtime.toISOString(), mimeType, target, name: path.basename(target), size: info.size, modifiedAt: info.mtime.toISOString(), kind, tooLarge: kind === 'text' && info.size > TEXT_LIMIT };
    const headers = { 'Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff' };
    if (url.searchParams.get('content') === 'pdf') {
      if (kind !== 'pdf') throw new FilePolicyError('UNSUPPORTED_FORMAT', 415, 'This file is not a PDF.');
      // Stream from the validated descriptor, bounded to the observed length; never buffer an uncapped PDF.
      const stream = handle.createReadStream({ autoClose: true, start: 0, end: Math.max(0, info.size - 1) });
      document = undefined;
      const { Readable } = await import('node:stream');
      return new Response(Readable.toWeb(stream) as ReadableStream, { headers: { ...headers, 'Content-Type': 'application/pdf', 'Content-Length': String(info.size), 'Content-Disposition': 'inline' } });
    }
    if (kind !== 'text' || metadata.tooLarge) return NextResponse.json({ ...metadata, content: null, reason: metadata.tooLarge ? 'TEXT_LIMIT_EXCEEDED' : kind === 'office' ? 'NATIVE_PREVIEW' : kind === 'pdf' ? 'PDF_VIEWER' : 'UNSUPPORTED_FORMAT' }, { headers });
    const buffer = Buffer.alloc(Math.min(info.size + 1, TEXT_LIMIT + 1));
    let offset = 0;
    while (offset < buffer.length) {
      const read = await handle.read(buffer, offset, buffer.length - offset, offset);
      if (!read.bytesRead) break;
      offset += read.bytesRead;
    }
    const after = await handle.stat();
    if (offset > TEXT_LIMIT || after.size !== info.size || after.mtimeMs !== info.mtimeMs) throw new FilePolicyError('FILE_CHANGED', 409, 'File changed while reading. Retry the preview.');
    if (buffer.subarray(0, offset).includes(0)) return NextResponse.json({ ...metadata, kind: 'unsupported' }, { headers });
    return NextResponse.json({ ...metadata, content: buffer.subarray(0, offset).toString('utf8') }, { headers });
  } catch (error) {
    // The existing root policy has its own truthful typed errors.
    const typed = error as { status?: number; code?: string; type?: string; message?: string };
    const errorCode = typed?.code ?? typed?.type;
    const result = typeof typed?.status === 'number' && typeof errorCode === 'string'
      ? { status: typed.status, body: { error: { code: errorCode, message: typed.message } } } : fileError(error);
    return NextResponse.json(result.body, { status: result.status, headers: { 'Cache-Control': 'no-store' } });
  } finally { await document?.handle.close(); }
}

'use client';

import React, { useEffect, useMemo, useState } from 'react';
import { resolveDocumentViewState } from '../../lib/shell/document-view-state';
import { useWorkspace } from '../workspace/workspace-provider';
import { ChatMarkdown } from './chat-markdown';

type Deliverable = {
  id: string;
  name: string;
  pkg: string;
  status: string;
  path: string;
};

type DeliverablesResponse = {
  deliverables?: Deliverable[];
  deliverableContracts?: Array<{
    path: string;
    selectedProductionDocuments: Array<{ fileName: string }>;
  }>;
  error?: { message?: string };
};

type ContentResponse = {
  content?: string;
  file?: string;
  error?: { message?: string };
};

// The well-known deliverable document files (see the knowledge buckets in
// `lib/workspace/filesystem.ts`). `_STATUS.md` is always present; the rest are
// offered so the viewer can open whichever the deliverable contains. A missing
// file simply surfaces the endpoint's 404.
const CONTROL_PLANE_DOCUMENT_FILES = [
  '_STATUS.md',
  '_CONTEXT.md',
  '_REFERENCES.md',
  '_DEPENDENCIES.md',
  '_SEMANTIC.md',
  'MEMORY.md'
];

const DEFAULT_FILE = '_STATUS.md';

function LegacyDocumentView(): JSX.Element {
  const { projectRoot } = useWorkspace();
  const [deliverables, setDeliverables] = useState<Deliverable[]>([]);
  const [canonicalDocumentsByPath, setCanonicalDocumentsByPath] = useState<
    Record<string, string[]>
  >({});
  const [rosterLoading, setRosterLoading] = useState(false);
  const [rosterError, setRosterError] = useState<string | null>(null);
  const [selectedPath, setSelectedPath] = useState<string>('');
  const [selectedFile, setSelectedFile] = useState<string>(DEFAULT_FILE);

  const [content, setContent] = useState<string | null>(null);
  const [contentLoading, setContentLoading] = useState(false);
  const [contentError, setContentError] = useState<string | null>(null);

  // Load the deliverable roster whenever the Working Root changes.
  useEffect(() => {
    let cancelled = false;
    setDeliverables([]);
    setCanonicalDocumentsByPath({});
    setRosterError(null);
    setSelectedPath('');
    setContent(null);
    setContentError(null);

    if (!projectRoot) {
      setRosterLoading(false);
      return () => {
        cancelled = true;
      };
    }

    setRosterLoading(true);

    async function loadRoster(): Promise<void> {
      try {
        const response = await fetch(
          `/api/project/deliverables?projectRoot=${encodeURIComponent(projectRoot as string)}`
        );
        const payload = (await response.json()) as DeliverablesResponse;
        if (cancelled) {
          return;
        }
        if (!response.ok || !payload.deliverables) {
          throw new Error(payload.error?.message ?? 'Unable to load deliverables.');
        }
        setDeliverables(payload.deliverables);
        setCanonicalDocumentsByPath(
          Object.fromEntries(
            (payload.deliverableContracts ?? []).map((contract) => [
              contract.path,
              contract.selectedProductionDocuments.map((file) => file.fileName)
            ])
          )
        );
        setSelectedPath(payload.deliverables[0]?.path ?? '');
      } catch (error) {
        if (cancelled) {
          return;
        }
        setRosterError(error instanceof Error ? error.message : 'Unable to load deliverables.');
      } finally {
        if (!cancelled) {
          setRosterLoading(false);
        }
      }
    }

    void loadRoster();
    return () => {
      cancelled = true;
    };
  }, [projectRoot]);

  // Fetch the selected document content.
  useEffect(() => {
    let cancelled = false;
    if (!projectRoot || !selectedPath) {
      setContent(null);
      setContentError(null);
      setContentLoading(false);
      return () => {
        cancelled = true;
      };
    }

    async function loadContent(): Promise<void> {
      setContentLoading(true);
      setContentError(null);
      try {
        const response = await fetch(
          `/api/working-root/deliverable/content?projectRoot=${encodeURIComponent(
            projectRoot as string
          )}&deliverablePath=${encodeURIComponent(selectedPath)}&file=${encodeURIComponent(
            selectedFile
          )}`
        );
        const payload = (await response.json()) as ContentResponse;
        if (cancelled) {
          return;
        }
        if (!response.ok || typeof payload.content !== 'string') {
          throw new Error(payload.error?.message ?? 'Unable to load document.');
        }
        setContent(payload.content);
      } catch (error) {
        if (cancelled) {
          return;
        }
        setContent(null);
        setContentError(error instanceof Error ? error.message : 'Unable to load document.');
      } finally {
        if (!cancelled) {
          setContentLoading(false);
        }
      }
    }

    void loadContent();
    return () => {
      cancelled = true;
    };
  }, [projectRoot, selectedPath, selectedFile]);

  const documentFiles = useMemo(
    () => [
      CONTROL_PLANE_DOCUMENT_FILES[0],
      ...(canonicalDocumentsByPath[selectedPath] ?? []),
      ...CONTROL_PLANE_DOCUMENT_FILES.slice(1)
    ],
    [canonicalDocumentsByPath, selectedPath]
  );

  const body = useMemo(() => {
    const state = resolveDocumentViewState({
      hasProjectRoot: Boolean(projectRoot),
      rosterLoading,
      rosterError,
      deliverableCount: deliverables.length,
      contentLoading,
      contentError,
      hasContent: content !== null
    });

    switch (state.kind) {
      case 'no-root':
        return <p className="panel-empty">Select a Working Root to view deliverable documents.</p>;
      case 'roster-loading':
        return <p className="panel-empty">Loading deliverables...</p>;
      case 'roster-error':
        return <p className="panel-error">{state.message}</p>;
      case 'empty':
        return <p className="panel-empty">No deliverables found in this Working Root.</p>;
      case 'content-loading':
        return <p className="panel-empty">Loading document...</p>;
      case 'content-error':
        return <p className="panel-error">{state.message}</p>;
      case 'content':
        return <ChatMarkdown source={content as string} />;
      case 'idle':
      default:
        return <p className="panel-empty">Select a deliverable and document to preview.</p>;
    }
  }, [projectRoot, rosterLoading, rosterError, deliverables, contentLoading, contentError, content]);

  return (
    <aside className="panel panel--document">
      <header className="panel-header">
        <h2>Document</h2>
        {deliverables.length > 0 ? (
          <div className="document-view-controls">
            <label className="document-view-selector">
              <span>Deliverable</span>
              <select
                value={selectedPath}
                onChange={(event) => {
                  setSelectedPath(event.target.value);
                  setSelectedFile(DEFAULT_FILE);
                }}
              >
                {deliverables.map((deliverable) => (
                  <option key={deliverable.path} value={deliverable.path}>
                    {deliverable.id} — {deliverable.name}
                  </option>
                ))}
              </select>
            </label>
            <label className="document-view-selector">
              <span>File</span>
              <select
                value={selectedFile}
                onChange={(event) => {
                  setSelectedFile(event.target.value);
                }}
              >
                {documentFiles.map((file) => (
                  <option key={file} value={file}>
                    {file}
                  </option>
                ))}
              </select>
            </label>
          </div>
        ) : null}
      </header>
      <div className="panel-body document-view-body">{body}</div>
    </aside>
  );
}


type FilePreview = {
  target: string; name: string; size: number; modifiedAt: string;
  kind: 'text' | 'pdf' | 'office' | 'unsupported'; tooLarge: boolean; content?: string;
};
type DocumentBridge = { document?: { inlinePdfPreview?: boolean; handoff: (input: { projectRoot: string; target: string; action: 'quick-look' | 'open' }) => Promise<{ ok: boolean; error?: { message?: string } }> } };

export async function handoffDocument(input: { projectRoot: string; target: string; action: 'quick-look' | 'open' }): Promise<void> {
  const bridge = typeof window === 'undefined' ? undefined : (window as unknown as { chirality?: DocumentBridge }).chirality?.document;
  if (!bridge) throw new Error('Open the desktop app to use native document actions.');
  const result = await bridge.handoff(input);
  if (!result.ok) throw new Error(result.error?.message ?? 'Unable to open the file.');
}

// Quoted CSV fields can contain commas and newlines. Stop after 500 logical rows.
export function previewCsv(source: string): string[][] {
  const rows: string[][] = []; let row: string[] = [], field = '', quoted = false;
  const cell = () => { if (row.length < 200) row.push(field); field = ''; };
  for (let i = 0; i < source.length && rows.length < 500; i++) {
    const char = source[i];
    if (char === '"') {
      if (quoted && source[i + 1] === '"') { field += '"'; i++; }
      else quoted = !quoted;
    } else if (char === ',' && !quoted) cell();
    else if (char === '\n' && !quoted) { cell(); rows.push(row); row = []; }
    else if (char !== '\r' || quoted) field += char;
  }
  if (rows.length < 500 && (row.length || field)) { cell(); rows.push(row); }
  return rows;
}

function FileDocumentView({ target }: { target: string }): JSX.Element {
  const { projectRoot } = useWorkspace();
  const [loaded, setLoaded] = useState<{ key: string; preview?: FilePreview; error?: string } | null>(null);
  const [reload, setReload] = useState(0);
  const [actionError, setActionError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const key = JSON.stringify([projectRoot, target, reload]);
  const url = `/api/working-root/file?projectRoot=${encodeURIComponent(projectRoot ?? '')}&target=${encodeURIComponent(target)}`;
  useEffect(() => {
    let cancelled = false;
    setActionError(null);
    if (projectRoot) void fetch(url).then(async response => {
      const preview = await response.json();
      if (!response.ok) throw new Error(preview.error?.message ?? 'Unable to load file.');
      if (!cancelled) setLoaded({ key, preview });
    }).catch(error => { if (!cancelled) setLoaded({ key, error: error instanceof Error ? error.message : 'Unable to load file.' }); });
    return () => { cancelled = true; };
  }, [key, projectRoot, url]);
  const preview = loaded?.key === key ? loaded.preview : undefined;
  const error = loaded?.key === key ? loaded.error : undefined;
  const desktop = typeof window === 'undefined' ? undefined : (window as unknown as { chirality?: DocumentBridge }).chirality;
  const bridge = desktop?.document;
  const inlinePdfPreview = !desktop || bridge?.inlinePdfPreview === true;
  const handoff = async (action: 'quick-look' | 'open') => {
    if (!projectRoot || !bridge) return;
    setBusy(true); setActionError(null);
    try {
      await handoffDocument({ projectRoot, target, action });
    } catch (error) { setActionError(error instanceof Error ? error.message : 'Unable to open the file.'); }
    finally { setBusy(false); }
  };
  const markdown = /\.(md|markdown)$/i.test(target);
  const csv = /\.csv$/i.test(target);
  return <section className="panel panel--document" aria-label="Document preview">
    <header className="panel-header"><h2>{preview?.name ?? target.split('/').at(-1)}</h2>
      <button type="button" onClick={() => setReload(value => value + 1)}>Reload</button></header>
    <div className="panel-body document-view-body" style={{ overflow: 'auto', overflowWrap: 'anywhere', minWidth: 0 }}>
      {!projectRoot ? <p>Choose a folder to see its files.</p> : error ? <p role="alert">{error}</p> : !preview ? <p>Loading document…</p> : <>
        <p>{preview.size.toLocaleString()} bytes · Modified {preview.modifiedAt}</p>
        {preview.kind === 'pdf' ? inlinePdfPreview ? <iframe title={preview.name} src={`${url}&content=pdf`} style={{ width: '100%', height: '65vh', border: 0 }} /> : <p>PDF preview is unavailable here. Open this file in its default app.</p> :
          preview.kind === 'text' && !preview.tooLarge ? (
            markdown ? <ChatMarkdown source={preview.content ?? ''} /> : csv ? <>
              <p>Preview: first 500 rows, up to 200 columns.</p>
              <div style={{ overflow: 'auto' }}><table><tbody>{previewCsv(preview.content ?? '').map((row, i) => <tr key={i}>{row.map((value, j) => <td key={j}>{value}</td>)}</tr>)}</tbody></table></div>
            </> : <pre style={{ whiteSpace: 'pre-wrap', overflowWrap: 'anywhere' }}>{preview.content}</pre>
          ) : <p>{preview.tooLarge ? 'This file exceeds the 10 MB text preview limit.' : preview.kind === 'office' ? 'Preview this Office document with Quick Look.' : 'This format is available in its default app.'}</p>}
        {preview.kind === 'office' ? <button type="button" disabled={!bridge || busy} onClick={() => void handoff('quick-look')}>Quick Look</button> : null}
        <button type="button" disabled={!bridge || busy} onClick={() => void handoff('open')}>Open in default app</button>
        {!bridge ? <p>Open the desktop app to use native document actions.</p> : null}
      </>}
      {actionError ? <p role="alert">{actionError}</p> : null}
    </div>
  </section>;
}

/** Optional file target extends, rather than replaces, the deliverable document viewer. */
export function DocumentView({ target }: { target?: string } = {}): JSX.Element {
  return target === undefined ? <LegacyDocumentView /> : <FileDocumentView key={target} target={target} />;
}
